import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Sparkles, Loader2, ArrowRight } from 'lucide-react';
import { generateMarketingInsight } from '../services/geminiService';

const Insights: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [result, setResult] = useState<{ text: string, trends: string[] } | null>(null);
  const [loading, setLoading] = useState(false);

  const handleGenerate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!topic.trim()) return;

    setLoading(true);
    setResult(null);

    const data = await generateMarketingInsight(topic);
    setResult(data);
    setLoading(false);
  };

  return (
    <section id="insights" className="py-24 bg-[#050505] border-t border-white/5 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 right-0 w-1/2 h-1/2 bg-blue-900/10 rounded-full blur-[120px] pointer-events-none"></div>

      <div className="container mx-auto px-6 relative z-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-16 items-center">
          <div>
            <div className="flex items-center gap-2 text-blue-500 mb-6">
              <Sparkles className="w-5 h-5" />
              <span className="font-bold tracking-widest text-sm uppercase">NADAUN AI Lab</span>
            </div>

            <h2 className="text-4xl md:text-5xl font-bold mb-8 leading-tight">
              Predict the Future <br/>
              <span className="text-gray-500">of Your Brand</span>
            </h2>

            <p className="text-gray-400 mb-12 text-lg leading-relaxed">
              Leverage our proprietary AI engine powered by Gemini to extract instant marketing insights and trend forecasts tailored to your industry.
            </p>

            <form onSubmit={handleGenerate} className="relative max-w-md">
              <input 
                type="text" 
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder="Enter industry (e.g., EV Cars, K-Beauty)"
                className="w-full bg-white/5 border border-white/10 rounded-full py-4 px-6 text-white placeholder-gray-500 focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all pr-16"
              />
              <button 
                type="submit"
                disabled={loading}
                className="absolute right-2 top-2 p-2 bg-blue-600 rounded-full hover:bg-blue-500 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : <ArrowRight className="w-6 h-6" />}
              </button>
            </form>
          </div>

          <div className="bg-white/5 border border-white/10 rounded-2xl p-8 md:p-12 min-h-[400px] flex flex-col justify-center relative backdrop-blur-sm">
            {!result && !loading && (
              <div className="text-center text-gray-500">
                <Sparkles className="w-12 h-12 mx-auto mb-4 opacity-20" />
                <p>Enter a topic to generate AI insights.</p>
              </div>
            )}

            {loading && (
              <div className="flex flex-col items-center justify-center space-y-4">
                <div className="w-16 h-1 bg-gray-800 rounded-full overflow-hidden">
                  <div className="h-full bg-blue-500 animate-progress"></div>
                </div>
                <p className="text-sm text-gray-400 animate-pulse">Analyzing market trends...</p>
              </div>
            )}

            {result && (
              <motion.div 
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.5 }}
              >
                <div className="mb-8">
                  <h4 className="text-xs font-bold text-blue-400 uppercase tracking-widest mb-3">Strategic Insight</h4>
                  <p className="text-xl md:text-2xl font-light leading-relaxed text-white">
