          animation: progress 1s infinite ease-in-out;
        }
      `}</style>
    </section>
  );
};

export default Insights;

import React, { useEffect, useState } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import About from './components/About';
import Business from './components/Business';
import Work from './components/Work';
import Insights from './components/Insights';
import Footer from './components/Footer';
import { motion, useScroll, useSpring } from 'framer-motion';

const App: React.FC = () => {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return (
    <div className="bg-black min-h-screen text-white selection:bg-blue-500 selection:text-white cursor-none">
      {/* Progress Bar */}
      <motion.div
        className="fixed top-0 left-0 right-0 h-1 bg-blue-600 origin-left z-[60]"
        style={{ scaleX }}
      />

      {/* Custom Cursor */}
      <div 
        className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
        style={{ 
          left: mousePosition.x, 
          top: mousePosition.y,
          transition: 'width 0.2s, height 0.2s',
        }}
      />

      <Header />

      <main>
        <Hero />
        <About />
        <Business />
        <Work />
        <Insights />
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Text, Html, PerspectiveCamera, OrthographicCamera, Float, Stars } from '@react-three/drei';
import * as THREE from 'three';
import { motion } from 'framer-motion';

// --- Data for the 4 Islands ---
const ISLANDS = [
  { id: 0, name: "CREATIVE", label: "Motion & Design", color: "#3b82f6", position: [8, 0, 8] },
  { id: 1, name: "TECH", label: "Dev & Solution", color: "#10b981", position: [-8, 0, 8] },
  { id: 2, name: "MEDIA", label: "Ad Planning", color: "#f59e0b", position: [-8, 0, -8] },
  { id: 3, name: "DATA", label: "AI Insight", color: "#8b5cf6", position: [8, 0, -8] },
];

const CORE_COLOR = "#FFFF00"; // Yellow core/lines

// --- Sub-components ---

const ConnectionLine = ({ start, end }: { start: [number, number, number], end: [number, number, number] }) => {
  const ref = useRef<THREE.Mesh>(null);

  // Calculate length and rotation to connect two points
  const startVec = new THREE.Vector3(...start);
  const endVec = new THREE.Vector3(...end);
  const distance = startVec.distanceTo(endVec);
  const midPoint = startVec.clone().add(endVec).multiplyScalar(0.5);

  // Create cylinder connecting them
  return (
    <mesh position={midPoint} rotation={[0, Math.atan2(end[2] - start[2], end[0] - start[0]), Math.PI/2]}>
      <cylinderGeometry args={[0.05, 0.05, distance, 8]} />
      <meshBasicMaterial color={CORE_COLOR} transparent opacity={0.6} />
    </mesh>
  );
};

const Island = ({ data, isFocused, onClick }: { data: typeof ISLANDS[0], isFocused: boolean, onClick: () => void }) => {
  const meshRef = useRef<THREE.Mesh>(null);
  const [hovered, setHovered] = useState(false);

  useFrame((state) => {
    if (meshRef.current) {
      // Gentle float animation
      meshRef.current.position.y = Math.sin(state.clock.elapsedTime + data.id) * 0.2;
    }
  });

  return (
    <group position={new THREE.Vector3(...data.position)} onClick={(e) => { e.stopPropagation(); onClick(); }}>
      <Float speed={2} rotationIntensity={0.2} floatIntensity={0.5}>
        {/* Main Block */}
        <mesh 
          ref={meshRef}
          onPointerOver={() => setHovered(true)}
          onPointerOut={() => setHovered(false)}
        >
          <boxGeometry args={[3, 4, 3]} />
          <meshStandardMaterial 
            color={hovered || isFocused ? data.color : "#222"} 
            roughness={0.2}
            metalness={0.8}
            emissive={hovered || isFocused ? data.color : "#000"}
            emissiveIntensity={hovered || isFocused ? 0.5 : 0}
          />
        </mesh>

        {/* Top Highlight Platform */}
        <mesh position={[0, 2.05, 0]}>
          <boxGeometry args={[2.8, 0.1, 2.8]} />
          <meshBasicMaterial color={data.color} />
        </mesh>

        {/* Label Text */}
        <group position={[0, 3.5, 0]} rotation={[-Math.PI / 4, Math.PI / 4, 0]}> 
           {/* Rotate text to face isometric camera roughly */}
          <Text
            fontSize={0.8}
            color="white"
            anchorX="center"
            anchorY="middle"
            outlineWidth={0.02}
            outlineColor="#000"
          >
            {data.name}
          </Text>
          <Text
            position={[0, -0.6, 0]}
            fontSize={0.3}
            color="#ccc"
            anchorX="center"
            anchorY="middle"
          >
            {data.label}
          </Text>
        </group>

        {/* HTML Annotation on Focus */}
        {isFocused && (
          <Html position={[0, 2, 0]} center distanceFactor={15}>
            <div className="bg-black/80 backdrop-blur-md p-4 rounded-lg border border-white/20 text-white min-w-[200px] text-center transform scale-100 transition-all pointer-events-none">
              <h3 className="font-bold text-lg mb-1" style={{color: data.color}}>{data.name}</h3>
              <p className="text-sm text-gray-300">{data.label}</p>
              <div className="mt-2 text-xs text-gray-400">Click background to zoom out</div>
            </div>
          </Html>
        )}
      </Float>
    </group>
  );
};

const Scene = () => {
  const [focusId, setFocusId] = useState<number | null>(null);

  // Camera animation
  useFrame((state) => {
    // Default position
    let targetPos = new THREE.Vector3(20, 20, 20);
    let targetZoom = 30;

    // Focus position
    if (focusId !== null) {
      const island = ISLANDS[focusId];
      // Move camera closer to the island, keeping the isometric angle
      targetPos = new THREE.Vector3(
        island.position[0] + 10, 
        island.position[1] + 10, 
        island.position[2] + 10
      );
      targetZoom = 60; // Zoom in
    }

    state.camera.position.lerp(targetPos, 0.05);
    state.camera.zoom = THREE.MathUtils.lerp(state.camera.zoom, targetZoom, 0.05);
    state.camera.updateProjectionMatrix();

    // Make camera look at the target
    const currentLookAt = new THREE.Vector3(0, 0, 0);
    if (focusId !== null) {
        const island = ISLANDS[focusId];
        const targetLookAt = new THREE.Vector3(...island.position);
        // Simple interpolation of lookAt is complex in useFrame with OrbitControls
        // Instead we let OrbitControls handle user interaction when not focused,
        // and when focused we might fight controls or just let camera move.
        // For simplicity, we just move camera position and zoom.
        // A smarter way for OrbitControls: set its target.
    }
  });

  return (
    <>
      <ambientLight intensity={0.5} />
      <pointLight position={[10, 20, 10]} intensity={1} />
      <pointLight position={[-10, 10, -10]} intensity={0.5} color="blue" />

      {/* Center Core */}
      <mesh position={[0, 0, 0]}>
        <sphereGeometry args={[1, 32, 32]} />
        <meshStandardMaterial color={CORE_COLOR} emissive={CORE_COLOR} emissiveIntensity={2} />
      </mesh>
      <pointLight position={[0, 0, 0]} distance={10} intensity={2} color={CORE_COLOR} />

      {/* Islands & Connections */}
      {ISLANDS.map((island) => (
        <React.Fragment key={island.id}>
          <Island 
            data={island} 
            isFocused={focusId === island.id} 
            onClick={() => setFocusId(island.id)} 
          />
          <ConnectionLine start={[0, 0, 0]} end={island.position as [number, number, number]} />
        </React.Fragment>
      ))}

      {/* Floor Grid (Subtle) */}
      <gridHelper args={[60, 60, 0x333333, 0x111111]} position={[0, -4, 0]} />

      {/* Controls */}
      <OrbitControls 
        enableZoom={false} // Zoom is handled by click logic
        makeDefault 
        autoRotate={focusId === null}
        autoRotateSpeed={0.5}
        target={focusId !== null ? ISLANDS[focusId].position : [0, 0, 0]}
        onStart={() => setFocusId(null)} // Reset focus on drag
      />

      {/* Background click to reset */}
      <mesh position={[0, -5, 0]} rotation={[-Math.PI/2, 0, 0]} onClick={() => setFocusId(null)}>
        <planeGeometry args={[100, 100]} />
        <meshBasicMaterial visible={false} />
      </mesh>
    </>
  );
};

const IsoWorld: React.FC = () => {
  return (
    <section className="h-[80vh] w-full bg-[#050505] relative overflow-hidden border-t border-b border-white/10">
      <div className="absolute top-8 left-8 z-10 pointer-events-none">
        <h2 className="text-4xl md:text-5xl font-bold tracking-tight">
          NADAUN <br/> <span className="text-[#FFFF00]">WORLD</span>
        </h2>
        <p className="text-gray-400 mt-2 max-w-xs text-sm">
          Explore our connected ecosystem. <br/> Drag to rotate, Click to explore.
        </p>
      </div>

      <Canvas
        shadows
        orthographic
        camera={{ position: [20, 20, 20], zoom: 30, near: 0.1, far: 1000 }}
        className="w-full h-full cursor-move"
      >
        <Scene />
        <Stars radius={100} depth={50} count={5000} factor={4} saturation={0} fade speed={1} />
      </Canvas>

      {/* Decorative Corners */}
      <div className="absolute top-0 left-0 w-32 h-32 border-l border-t border-white/10"></div>
      <div className="absolute bottom-0 right-0 w-32 h-32 border-r border-b border-white/10"></div>
    </section>
  );
};

export default IsoWorld;

import React, { useEffect, useState } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import IsoWorld from './components/IsoWorld';
import About from './components/About';
import Business from './components/Business';
import Work from './components/Work';
import Insights from './components/Insights';
import Footer from './components/Footer';
import { motion, useScroll, useSpring } from 'framer-motion';

const App: React.FC = () => {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return (
    <div className="bg-black min-h-screen text-white selection:bg-blue-500 selection:text-white cursor-none">
      {/* Progress Bar */}
      <motion.div
        className="fixed top-0 left-0 right-0 h-1 bg-blue-600 origin-left z-[60]"
        style={{ scaleX }}
      />

      {/* Custom Cursor */}
      <div 
        className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
        style={{ 
          left: mousePosition.x, 
          top: mousePosition.y,
          transition: 'width 0.2s, height 0.2s',
        }}
      />

      <Header />

      <main>
        <Hero />
        <IsoWorld />
        <About />
        <Business />
        <Work />
        <Insights />
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useRef, useState, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Text, Html, Float, Stars } from '@react-three/drei';
import * as THREE from 'three';

// --- Data for the 4 Islands ---
const ISLANDS = [
  { id: 0, name: "CREATIVE", label: "Motion & Design", color: "#3b82f6", position: [8, 0, 8] },
  { id: 1, name: "TECH", label: "Dev & Solution", color: "#10b981", position: [-8, 0, 8] },
  { id: 2, name: "MEDIA", label: "Ad Planning", color: "#f59e0b", position: [-8, 0, -8] },
  { id: 3, name: "DATA", label: "AI Insight", color: "#8b5cf6", position: [8, 0, -8] },
];

const CORE_COLOR = "#FFFF00"; // Yellow core/lines

// --- Sub-components ---

const ConnectionLine = ({ start, end }: { start: number[], end: number[] }) => {
  // Use useMemo to calculate geometry data once
  const { position, rotation, height } = useMemo(() => {
    const startVec = new THREE.Vector3(...start);
    const endVec = new THREE.Vector3(...end);
    const dist = startVec.distanceTo(endVec);

    // Midpoint position
    const mid = startVec.clone().add(endVec).multiplyScalar(0.5);

    // Rotation: Point cylinder along the path
    // Cylinder default is Y-axis. We create a dummy object to calculate lookAt rotation, then adjust.
    const obj = new THREE.Object3D();
    obj.position.copy(mid);
    obj.lookAt(endVec);
    obj.rotateX(Math.PI / 2); // Rotate to align Cylinder's Y axis with the look direction (Z)

    return {
      position: mid,
      rotation: obj.rotation,
      height: dist
    };
  }, [start, end]);

  return (
    <mesh position={position} rotation={rotation}>
      <cylinderGeometry args={[0.05, 0.05, height, 8]} />
      <meshBasicMaterial color={CORE_COLOR} transparent opacity={0.6} />
    </mesh>
  );
};

const Island = ({ data, isFocused, onClick }: { data: typeof ISLANDS[0], isFocused: boolean, onClick: () => void }) => {
  const meshRef = useRef<THREE.Mesh>(null);
