          onPointerOver={() => setHovered(true)}
          onPointerOut={() => setHovered(false)}
        >
          <boxGeometry args={[3, 4, 3]} />
          <meshStandardMaterial 
            color={hovered || isFocused ? data.color : "#222"} 
            roughness={0.2}
            metalness={0.8}
            emissive={hovered || isFocused ? data.color : "#000"}
            emissiveIntensity={hovered || isFocused ? 0.5 : 0}
          />
        </mesh>

        {/* Top Highlight Platform */}
        <mesh position={[0, 2.05, 0]}>
          <boxGeometry args={[2.8, 0.1, 2.8]} />
          <meshBasicMaterial color={data.color} />
        </mesh>

        {/* Label Text */}
        <group position={[0, 3.5, 0]} rotation={[-Math.PI / 4, Math.PI / 4, 0]}> 
           {/* Rotate text to face isometric camera roughly */}
          <Text
            fontSize={0.8}
            color="white"
            anchorX="center"
            anchorY="middle"
            outlineWidth={0.02}
            outlineColor="#000"
          >
            {data.name}
          </Text>
          <Text
            position={[0, -0.6, 0]}
            fontSize={0.3}
            color="#ccc"
            anchorX="center"
            anchorY="middle"
          >
            {data.label}
          </Text>
        </group>

        {/* HTML Annotation on Focus */}
        {isFocused && (
          <Html position={[0, 2, 0]} center distanceFactor={15} style={{ pointerEvents: 'none' }}>
            <div className="bg-black/80 backdrop-blur-md p-4 rounded-lg border border-white/20 text-white min-w-[200px] text-center transform scale-100 transition-all shadow-xl shadow-black/50">
              <h3 className="font-bold text-lg mb-1 tracking-wider" style={{color: data.color}}>{data.name}</h3>
              <p className="text-sm text-gray-300">{data.label}</p>
              <div className="mt-3 text-xs text-gray-500 uppercase tracking-widest">Active Zone</div>
            </div>
          </Html>
        )}
      </Float>
    </group>
  );
};

const Scene = () => {
  const [focusId, setFocusId] = useState<number | null>(null);

  useFrame((state) => {
    // Default Isometric Position
    let targetPos = new THREE.Vector3(20, 20, 20);
    let targetZoom = 30;

    // Focus Logic
    if (focusId !== null) {
      const island = ISLANDS[focusId];
      // Keep the isometric angle (1,1,1 direction) but move closer
      targetPos = new THREE.Vector3(
        island.position[0] + 10, 
        island.position[1] + 10, 
        island.position[2] + 10
      );
      targetZoom = 55; // Zoom in
    }

    // Smooth Camera Transition
    state.camera.position.lerp(targetPos, 0.04);
    state.camera.zoom = THREE.MathUtils.lerp(state.camera.zoom, targetZoom, 0.04);
    state.camera.updateProjectionMatrix();
  });

  return (
    <>
      <ambientLight intensity={0.4} />
      <pointLight position={[10, 20, 10]} intensity={1.5} />
      <pointLight position={[-10, 10, -10]} intensity={0.5} color="#4c1d95" />

      {/* Center Core */}
      <group>
        <mesh position={[0, 0, 0]}>
          <octahedronGeometry args={[1, 0]} />
          <meshStandardMaterial color={CORE_COLOR} emissive={CORE_COLOR} emissiveIntensity={3} wireframe />
        </mesh>
        <mesh position={[0, 0, 0]}>
          <octahedronGeometry args={[0.8, 0]} />
          <meshBasicMaterial color="#fff" />
        </mesh>
      </group>
      <pointLight position={[0, 0, 0]} distance={15} intensity={2} color={CORE_COLOR} />

      {/* Islands & Connections */}
      {ISLANDS.map((island) => (
        <React.Fragment key={island.id}>
          <Island 
            data={island} 
            isFocused={focusId === island.id} 
            onClick={() => setFocusId(island.id)} 
          />
          <ConnectionLine start={[0, 0, 0]} end={island.position} />
        </React.Fragment>
      ))}

      {/* Floor Grid (Subtle) */}
      <gridHelper args={[60, 40, 0x333333, 0x111111]} position={[0, -4, 0]} />

      {/* Controls */}
      <OrbitControls 
        makeDefault
        enableZoom={false}
        enablePan={false}
        autoRotate={focusId === null}
        autoRotateSpeed={0.8}
        // Sync target with focus to keep rotation center correct
        target={focusId !== null ? new THREE.Vector3(...ISLANDS[focusId].position) : new THREE.Vector3(0,0,0)}
        onStart={() => setFocusId(null)} 
      />

      {/* Background click handler to zoom out */}
      <mesh position={[0, -5, 0]} rotation={[-Math.PI/2, 0, 0]} onClick={() => setFocusId(null)}>
        <planeGeometry args={[200, 200]} />
        <meshBasicMaterial visible={false} />
      </mesh>
    </>
  );
};

const IsoWorld: React.FC = () => {
  return (
    <section className="h-[80vh] w-full bg-[#050505] relative overflow-hidden border-t border-b border-white/10">
      <div className="absolute top-8 left-8 z-10 pointer-events-none select-none">
        <h2 className="text-4xl md:text-5xl font-bold tracking-tight">
          NADAUN <br/> <span className="text-[#FFFF00]">WORLD</span>
        </h2>
        <p className="text-gray-400 mt-4 max-w-xs text-sm leading-relaxed border-l-2 border-[#FFFF00] pl-4">
          Experience our connected ecosystem.<br/> 
          <span className="text-white/60">Drag to rotate • Click to explore</span>
        </p>
      </div>

      <Canvas
        shadows
        orthographic
        camera={{ position: [20, 20, 20], zoom: 30, near: 0.1, far: 1000 }}
        className="w-full h-full cursor-move"
        dpr={[1, 2]} // Optimize for high DPI screens
      >
        <Scene />
        <Stars radius={100} depth={50} count={3000} factor={4} saturation={0} fade speed={0.5} />
      </Canvas>

      {/* UI Overlays */}
      <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-black/80 to-transparent pointer-events-none"></div>
      <div className="absolute bottom-0 left-0 w-full h-32 bg-gradient-to-t from-black/80 to-transparent pointer-events-none"></div>
    </section>
  );
};

export default IsoWorld;

