// --- Helper Components ---

const ConnectionLine = ({ start, end }: { start: number[], end: number[] }) => {
  const { position, rotation, height } = useMemo(() => {
    const startVec = new THREE.Vector3(...start);
    const endVec = new THREE.Vector3(...end);
    const dist = startVec.distanceTo(endVec);
    const mid = startVec.clone().add(endVec).multiplyScalar(0.5);
    const obj = new THREE.Object3D();
    obj.position.copy(mid);
    obj.lookAt(endVec);
    obj.rotateX(Math.PI / 2);
    return { position: mid, rotation: obj.rotation, height: dist };
  }, [start, end]);

  return (
    <group>
      {/* Glowing Core Line */}
      <mesh position={position} rotation={rotation}>
        <cylinderGeometry args={[0.08, 0.08, height, 8]} />
        <meshBasicMaterial color={CORE_COLOR} />
      </mesh>
      {/* Animated Pulse Packet (Simulated with transparent larger cylinder) */}
      <mesh position={position} rotation={rotation}>
         <cylinderGeometry args={[0.2, 0.2, height, 8]} />
         <meshBasicMaterial color={CORE_COLOR} transparent opacity={0.15} depthWrite={false} />
      </mesh>
    </group>
  );
};

const Island = ({ data, isFocused, onClick }: { data: typeof ISLANDS[0], isFocused: boolean, onClick: () => void }) => {
  const [hovered, setHovered] = useState(false);
  const groupRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (groupRef.current) {
      // Base floating animation
      groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.5 + data.id) * 0.3;
    }
  });

  // Select Model based on type
  const renderModel = () => {
    switch (data.type) {
      case "SPACE": return <SpaceModel color={data.color} />;
      case "STUDIO": return <StudioModel color={data.color} />;
      case "PROJECT": return <ProjectModel color={data.color} />;
      case "NAN": return <NanModel color={data.color} />;
      default: return null;
    }
  };

  return (
    <group 
      position={new THREE.Vector3(...data.position)} 
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      onPointerOver={() => setHovered(true)}
      onPointerOut={() => setHovered(false)}
    >
      <group ref={groupRef}>
        <Float speed={2} rotationIntensity={0.1} floatIntensity={0.5}>
          {renderModel()}

          {/* Base Platform Shadow/Glow */}
          <mesh position={[0, -1, 0]} rotation={[-Math.PI/2, 0, 0]}>
            <circleGeometry args={[3.5, 32]} />
            <meshBasicMaterial color={data.color} transparent opacity={hovered || isFocused ? 0.3 : 0.1} depthWrite={false} />
          </mesh>

          {/* Label Text */}
          <group position={[0, 4.5, 0]} rotation={[-Math.PI / 4, Math.PI / 4, 0]}> 
            <Text
              fontSize={0.7}
              color="white"
              anchorX="center"
              anchorY="middle"
              outlineWidth={0.04}
              outlineColor="#000"
              font="https://fonts.gstatic.com/s/manrope/v13/xn7_YHE41ni1AdIRqAuZuw1Bx9mbZk79FN_C-b_.woff2" // Fallback or standard font
            >
              {data.name}
            </Text>
            <Text
              position={[0, -0.6, 0]}
              fontSize={0.3}
              color={data.color}
              anchorX="center"
              anchorY="middle"
              outlineWidth={0.02}
              outlineColor="#000"
            >
              {data.label}
            </Text>
          </group>

          {/* HTML Annotation on Focus */}
          {isFocused && (
            <Html position={[0, 3, 0]} center distanceFactor={15} style={{ pointerEvents: 'none' }}>
              <div className="bg-black/90 backdrop-blur-xl p-6 rounded-xl border border-white/20 text-white min-w-[280px] text-center transform scale-100 transition-all shadow-2xl shadow-black/80">
                <div className="w-12 h-1 mb-4 mx-auto rounded-full" style={{ backgroundColor: data.color }}></div>
                <h3 className="font-extrabold text-2xl mb-2 tracking-tight">{data.name}</h3>
                <p className="text-sm text-gray-300 mb-4 leading-relaxed font-light">{data.label}</p>
                <div className="text-xs text-gray-500 uppercase tracking-[0.2em] border-t border-white/10 pt-3">
                  Interactive Module
                </div>
              </div>
            </Html>
          )}
        </Float>
      </group>
    </group>
  );
};

const Scene = () => {
  const [focusId, setFocusId] = useState<number | null>(null);

  useFrame((state) => {
    // Default Position
    let targetPos = new THREE.Vector3(24, 24, 24);
    let targetZoom = 30;

    // Focus Logic
    if (focusId !== null) {
      const island = ISLANDS[focusId];
      targetPos = new THREE.Vector3(
        island.position[0] + 12, 
        island.position[1] + 12, 
        island.position[2] + 12
      );
      targetZoom = 55;
    }

    state.camera.position.lerp(targetPos, 0.04);
    state.camera.zoom = THREE.MathUtils.lerp(state.camera.zoom, targetZoom, 0.04);
    state.camera.updateProjectionMatrix();
  });

  return (
    <>
      {/* Lighting */}
      <ambientLight intensity={0.5} />
      <directionalLight position={[10, 20, 5]} intensity={1.5} castShadow />
      <pointLight position={[-10, 5, -10]} intensity={2} color="#4c1d95" distance={30} />
      <pointLight position={[10, 5, 10]} intensity={2} color="#0ea5e9" distance={30} />

      {/* Center Core Hub */}
      <group>
        <mesh position={[0, 0, 0]}>
          <icosahedronGeometry args={[1.5, 0]} />
          <meshStandardMaterial color={CORE_COLOR} emissive={CORE_COLOR} emissiveIntensity={2} wireframe />
        </mesh>
        <Sparkles count={50} scale={4} size={2} speed={0.4} opacity={1} color={CORE_COLOR} />
      </group>

      {/* Islands & Connections */}
      {ISLANDS.map((island) => (
        <React.Fragment key={island.id}>
          <Island 
            data={island} 
            isFocused={focusId === island.id} 
            onClick={() => setFocusId(island.id)} 
          />
          <ConnectionLine start={[0, 0, 0]} end={island.position} />
        </React.Fragment>
      ))}

      {/* Floor Grid */}
      <gridHelper args={[80, 40, 0x333333, 0x050505]} position={[0, -4, 0]} />

      {/* Controls */}
      <OrbitControls 
        makeDefault
        enableZoom={false}
        enablePan={false}
        autoRotate={focusId === null}
        autoRotateSpeed={1.0}
        target={focusId !== null ? new THREE.Vector3(...ISLANDS[focusId].position) : new THREE.Vector3(0,0,0)}
        onStart={() => setFocusId(null)} 
      />

      {/* Reset Area */}
      <mesh position={[0, -10, 0]} rotation={[-Math.PI/2, 0, 0]} onClick={() => setFocusId(null)}>
        <planeGeometry args={[500, 500]} />
        <meshBasicMaterial visible={false} />
      </mesh>
    </>
  );
};

