const NanModel = ({ color }: { color: string }) => {
  const starRef = useRef<THREE.Mesh>(null);
  const lightsRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (starRef.current) {
      starRef.current.rotation.y = state.clock.elapsedTime * 0.5;
      starRef.current.rotation.z = Math.sin(state.clock.elapsedTime * 0.5) * 0.1;
    }
    if (lightsRef.current) {
       lightsRef.current.rotation.y = -state.clock.elapsedTime * 0.2;
    }
  });

  return (
    <group>
      {/* Stage Base */}
      <mesh position={[0, 0, 0]}>
        <cylinderGeometry args={[2.5, 3, 1, 64]} />
        <meshStandardMaterial color="#111" metalness={0.9} roughness={0.1} />
      </mesh>
      <mesh position={[0, 0.51, 0]}>
        <cylinderGeometry args={[2.2, 2.2, 0.1, 64]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={2} toneMapped={false} />
      </mesh>

      {/* Floating Star */}
      <mesh ref={starRef} position={[0, 2.5, 0]}>
        <dodecahedronGeometry args={[1.2, 0]} />
        <meshPhysicalMaterial 
          color={color} 
          metalness={1} 
          roughness={0} 
          emissive={color}
          emissiveIntensity={1}
          clearcoat={1}
        />
        <Sparkles count={30} scale={4} size={3} speed={0.2} opacity={0.8} color="#fff" />
      </mesh>

      {/* Rotating Spotlights */}
      <group ref={lightsRef} position={[0, 0.5, 0]}>
        {[0, 1, 2].map((i) => (
          <mesh key={i} position={[Math.sin(i * 2.1) * 2, 0.5, Math.cos(i * 2.1) * 2]} rotation={[0.3, i * 2.1, 0]}>
            <coneGeometry args={[0.2, 0.8, 16]} />
            <meshStandardMaterial color="#333" />
            <mesh position={[0, 2, 0]}>
               <cylinderGeometry args={[0.02, 0.3, 4, 16]} />
               <meshBasicMaterial color={color} transparent opacity={0.1} depthWrite={false} blending={THREE.AdditiveBlending} />
            </mesh>
          </mesh>
        ))}
      </group>
    </group>
  );
};

// --- Helper Components ---

const ConnectionLine = ({ start, end }: { start: number[], end: number[] }) => {
  const { position, rotation, height } = useMemo(() => {
    const startVec = new THREE.Vector3(...start);
    const endVec = new THREE.Vector3(...end);
    const dist = startVec.distanceTo(endVec);
    const mid = startVec.clone().add(endVec).multiplyScalar(0.5);
    const obj = new THREE.Object3D();
    obj.position.copy(mid);
    obj.lookAt(endVec);
    obj.rotateX(Math.PI / 2);
    return { position: mid, rotation: obj.rotation, height: dist };
  }, [start, end]);

  return (
    <group>
      {/* Glowing Core Line */}
      <mesh position={position} rotation={rotation}>
        <cylinderGeometry args={[0.04, 0.04, height, 8]} />
        <meshBasicMaterial color={CORE_COLOR} />
      </mesh>
      {/* Animated Pulse Packet */}
      <mesh position={position} rotation={rotation}>
         <cylinderGeometry args={[0.15, 0.15, height, 8]} />
         <meshBasicMaterial color={CORE_COLOR} transparent opacity={0.1} depthWrite={false} blending={THREE.AdditiveBlending} />
      </mesh>
    </group>
  );
};

const Island = ({ data, isFocused, onClick }: { data: typeof ISLANDS[0], isFocused: boolean, onClick: () => void }) => {
  const [hovered, setHovered] = useState(false);
  const groupRef = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (groupRef.current) {
      // Smoother Float
      groupRef.current.position.y = Math.sin(state.clock.elapsedTime * 0.5 + data.id) * 0.2;
    }
  });

  const renderModel = () => {
    switch (data.type) {
      case "SPACE": return <SpaceModel color={data.color} />;
      case "STUDIO": return <StudioModel color={data.color} />;
      case "PROJECT": return <ProjectModel color={data.color} />;
      case "NAN": return <NanModel color={data.color} />;
      default: return null;
    }
  };

  return (
    <group 
      position={new THREE.Vector3(...data.position)} 
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      onPointerOver={() => { document.body.style.cursor = 'pointer'; setHovered(true); }}
      onPointerOut={() => { document.body.style.cursor = 'auto'; setHovered(false); }}
    >
      <group ref={groupRef}>
        <Float speed={1.5} rotationIntensity={0.05} floatIntensity={0.2} floatingRange={[-0.2, 0.2]}>
          {renderModel()}

          <mesh position={[0, -1, 0]} rotation={[-Math.PI/2, 0, 0]}>
            <circleGeometry args={[3.5, 64]} />
            <meshBasicMaterial color={data.color} transparent opacity={hovered || isFocused ? 0.2 : 0.05} depthWrite={false} />
          </mesh>

          {/* Label Text */}
          <group position={[0, 4.8, 0]} rotation={[-Math.PI / 4, Math.PI / 4, 0]}> 
            <Text
              fontSize={0.6}
              color="white"
              anchorX="center"
              anchorY="middle"
              outlineWidth={0.03}
              outlineColor="#000"
            >
              {data.name}
            </Text>
            <Text
              position={[0, -0.5, 0]}
              fontSize={0.25}
              color={data.color}
              anchorX="center"
              anchorY="middle"
              outlineWidth={0.01}
              outlineColor="#000"
            >
              {data.label}
            </Text>
          </group>

          {isFocused && (
            <Html position={[0, 3, 0]} center distanceFactor={15} style={{ pointerEvents: 'none', zIndex: 10 }}>
              <div className="bg-black/90 backdrop-blur-xl p-6 rounded-xl border border-white/20 text-white min-w-[280px] text-center transform scale-100 transition-all shadow-2xl shadow-black/80">
                <div className="w-12 h-1 mb-4 mx-auto rounded-full" style={{ backgroundColor: data.color }}></div>
                <h3 className="font-extrabold text-2xl mb-2 tracking-tight">{data.name}</h3>
                <p className="text-sm text-gray-300 mb-4 leading-relaxed font-light">{data.label}</p>
                <div className="text-xs text-gray-500 uppercase tracking-[0.2em] border-t border-white/10 pt-3">
                  Interactive Module
                </div>
              </div>
            </Html>
          )}
        </Float>
      </group>
    </group>
  );
};

const Scene = () => {
  const [focusId, setFocusId] = useState<number | null>(null);

  useFrame((state) => {
    let targetPos = new THREE.Vector3(24, 24, 24);
    let targetZoom = 30;

    if (focusId !== null) {
      const island = ISLANDS[focusId];
      targetPos = new THREE.Vector3(
        island.position[0] + 10, 
        island.position[1] + 10, 
        island.position[2] + 10
      );
      targetZoom = 50;
    }

    // Smoother camera lerp
    state.camera.position.lerp(targetPos, 0.03);
    state.camera.zoom = THREE.MathUtils.lerp(state.camera.zoom, targetZoom, 0.03);
    state.camera.updateProjectionMatrix();
  });

  return (
    <>
      {/* Advanced Lighting Environment */}
      <Environment preset="night" blur={0.8} />
      <ambientLight intensity={0.2} />
      <pointLight position={[-10, 5, -10]} intensity={1.5} color="#4c1d95" distance={40} decay={2} />
      <pointLight position={[10, 5, 10]} intensity={1.5} color="#0ea5e9" distance={40} decay={2} />

      <group>
        <mesh position={[0, 0, 0]}>
          <icosahedronGeometry args={[1.5, 0]} />
          <meshStandardMaterial color={CORE_COLOR} emissive={CORE_COLOR} emissiveIntensity={3} wireframe />
        </mesh>
        <Sparkles count={80} scale={6} size={3} speed={0.2} opacity={1} color={CORE_COLOR} />
      </group>

      {ISLANDS.map((island) => (
        <React.Fragment key={island.id}>
          <Island 
            data={island} 
            isFocused={focusId === island.id} 
            onClick={() => setFocusId(island.id)} 
          />
          <ConnectionLine start={[0, 0, 0]} end={island.position} />
        </React.Fragment>
      ))}

      {/* Subtle Floor Grid */}
      <gridHelper args={[80, 40, 0x333333, 0x050505]} position={[0, -4, 0]} />

      {/* Controls with Damping for smoothness */}
      <OrbitControls 
        makeDefault
        enableDamping={true}
        dampingFactor={0.05}
        enableZoom={false}
        enablePan={false}
        autoRotate={focusId === null}
        autoRotateSpeed={0.5}
        target={focusId !== null ? new THREE.Vector3(...ISLANDS[focusId].position) : new THREE.Vector3(0,0,0)}
        onStart={() => setFocusId(null)} 
      />

      <mesh position={[0, -10, 0]} rotation={[-Math.PI/2, 0, 0]} onClick={() => setFocusId(null)}>
        <planeGeometry args={[500, 500]} />
        <meshBasicMaterial visible={false} />
      </mesh>
    </>
  );
};

const IsoWorld: React.FC = () => {
  return (
    <section className="h-[90vh] w-full bg-[#020202] relative overflow-hidden border-t border-b border-white/5">
