const SpaceModel = ({ color }: { color: string }) => {
  const ringRef = useRef<THREE.Mesh>(null);
  useFrame((state) => {
    if (ringRef.current) {
      ringRef.current.rotation.z = state.clock.elapsedTime * 0.2; 
      ringRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.3) * 0.1;
    }
  });
  return (
    <group>
      <mesh position={[0, 1.5, 0]}>
        <boxGeometry args={[2, 5, 2]} />
        <meshPhysicalMaterial color="#ffffff" transmission={0.6} thickness={1.5} roughness={0.05} metalness={0.1} transparent opacity={0.9} />
      </mesh>
      <mesh position={[0, 1.5, 0]}>
        <boxGeometry args={[1.5, 4.8, 1.5]} />
        <meshStandardMaterial color={color} emissive={color} emissiveIntensity={0.6} />
      </mesh>
      <mesh ref={ringRef} position={[0, 2, 0]} rotation={[Math.PI/2, 0, 0]}>
        <torusGeometry args={[2.8, 0.05, 16, 100]} />
        <meshBasicMaterial color={color} />
      </mesh>
    </group>
  );
};

const StudioModel = ({ color }: { color: string }) => {
  const lensRef = useRef<THREE.Group>(null);
  useFrame((state) => {
    if (lensRef.current) {
      const scale = 1 + Math.sin(state.clock.elapsedTime * 1.5) * 0.02;
      lensRef.current.scale.set(scale, scale, scale);
    }
  });
  return (
    <group>
      <mesh position={[0, 1, 0]}>
        <boxGeometry args={[3.5, 3.5, 1.5]} />
        <meshStandardMaterial color="#111" roughness={0.2} metalness={0.8} />
