  useFrame((state) => {
    if (lensRef.current) {
      const scale = 1 + Math.sin(state.clock.elapsedTime * 1.5) * 0.02;
      lensRef.current.scale.set(scale, scale, scale);
    }
  });
  return (
    <group>
      <mesh position={[0, 1, 0]}>
