  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  // Smooth scroll parallax for the list container
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start end", "end start"]
  });

  // Parallax effect for the entire list block
  const yMove = useTransform(scrollYProgress, [0, 1], [50, -50]);

  // Handle mouse move for image reveal
  const handleMouseMove = (e: React.MouseEvent) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      setMousePos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      });
    }
  };

  return (
    <section 
      ref={containerRef} 
      className="bg-black text-white py-32 relative overflow-hidden cursor-default"
      onMouseMove={handleMouseMove}
      onMouseLeave={() => setHoveredIndex(null)}
    >
      <div className="container mx-auto px-6 relative z-10">
        <motion.div 
          style={{ y: yMove }}
          className="flex flex-col border-t border-white/20"
        >
          {/* Header with reveal animation */}
          <motion.div 
            initial={{ opacity: 0, y: 30 }}
            whileInView={{ opacity: 1, y: 0 }}
