      {/* Floating Image Reveal */}
      <div className="pointer-events-none absolute top-0 left-0 w-full h-full z-20 hidden md:block overflow-hidden">
        <AnimatePresence>
          {hoveredIndex !== null && (
            <motion.div
              initial={{ opacity: 0, scale: 0.8, filter: "blur(10px)" }}
              animate={{ 
                opacity: 1, 
                scale: 1,
                filter: "blur(0px)",
                x: mousePos.x - 200, 
                y: mousePos.y - 150
              }}
              exit={{ opacity: 0, scale: 0.8, filter: "blur(10px)" }}
              transition={{ type: "spring", stiffness: 150, damping: 20, mass: 0.1 }}
