    if (ringRef.current) {
      ringRef.current.rotation.z = state.clock.elapsedTime * 0.2; 
      ringRef.current.rotation.x = Math.sin(state.clock.elapsedTime * 0.3) * 0.1;
    }
  });
  return (
    <group>
