const StudioModel = ({ color }: { color: string }) => {
  const lensRef = useRef<THREE.Group>(null);
  useFrame((state) => {
    if (lensRef.current) {
      const scale = 1 + Math.sin(state.clock.elapsedTime * 1.5) * 0.02;
      lensRef.current.scale.set(scale, scale, scale);
    }
  });
  return (
    <group>
      <mesh position={[0, 1, 0]}>
        <boxGeometry args={[3.5, 3.5, 1.5]} />
        <meshStandardMaterial color="#1a1a1a" roughness={0.2} metalness={0.8} />
