const Hero: React.FC = () => {
  const [activeImage, setActiveImage] = useState(0);
  const lastMousePos = useRef({ x: 0, y: 0 });

  // Preload images to prevent flickering
  useEffect(() => {
    HERO_IMAGES.forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

  const handleMouseMove = (e: React.MouseEvent) => {
    // Drastically reduced threshold for high sensitivity (Montage Effect)
    const threshold = 15; 

    // Calculate distance from last update
    const dist = Math.hypot(
      e.clientX - lastMousePos.current.x,
      e.clientY - lastMousePos.current.y
    );

    if (dist > threshold) {
      setActiveImage((prev) => (prev + 1) % HERO_IMAGES.length);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const scrollToNext = () => {
    const nextSection = document.getElementById('isoworld');
    if (nextSection) {
      nextSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section 
      className="relative h-screen w-full flex items-center justify-center overflow-hidden bg-black cursor-none"
      onMouseMove={handleMouseMove}
    >
      {/* Background Images Layer */}
      <div className="absolute inset-0 z-0 select-none pointer-events-none">
        {HERO_IMAGES.map((src, index) => (
          <img
            key={index}
            src={src}
            alt="Hero Background"
            className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-0 ${
              activeImage === index ? 'opacity-100' : 'opacity-0'
            }`}
            style={{ filter: 'brightness(0.6) contrast(1.1)' }}
          />
        ))}
        {/* Gradient Overlay for Text Readability */}
        <div className="absolute inset-0 bg-black/20 z-10"></div>
      </div>

      {/* Main Content */}
      <div className="container mx-auto px-6 z-20 relative text-center pointer-events-none">
        <div className="flex flex-col items-center justify-center h-full mix-blend-difference">
          {/* Top Label */}
          <motion.div
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 1, delay: 0.5 }}
            className="mb-8"
          >
            <span className="text-xs md:text-sm font-bold tracking-[0.4em] text-[#FFB800] uppercase border border-[#FFB800] px-6 py-2 rounded-full backdrop-blur-sm">
              Total Creative Studio
            </span>
          </motion.div>

          {/* Main Title - Lowercase 'nadaun' */}
          <div className="relative">
            <div className="overflow-hidden">
              <motion.h1 
                initial={{ y: 150 }}
                animate={{ y: 0 }}
                transition={{ duration: 1, ease: [0.22, 1, 0.36, 1] }}
                className="text-[15vw] md:text-[13vw] font-extrabold tracking-tighter leading-[0.8] text-white lowercase"
              >
                nadaun
              </motion.h1>
            </div>
            <div className="overflow-hidden">
              <motion.h1 
                initial={{ y: 150 }}
                animate={{ y: 0 }}
                transition={{ duration: 1, delay: 0.15, ease: [0.22, 1, 0.36, 1] }}
                className="text-[5vw] md:text-[4vw] font-bold tracking-[0.5em] leading-[1] text-[#FFB800] mt-4"
              >
                COLLECTIVE
              </motion.h1>
            </div>
          </div>

          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1.2, duration: 1 }}
            className="mt-12 max-w-2xl mx-auto"
          >
            <p className="text-sm md:text-lg text-white font-medium tracking-widest uppercase flex items-center gap-4 justify-center">
              <span className="w-12 h-[1px] bg-white/50"></span>
              Move Cursor to Explore
              <span className="w-12 h-[1px] bg-white/50"></span>
