const HERO_IMAGES = [
  "https://images.unsplash.com/photo-1621784563330-caee0b138a00?q=80&w=2070&auto=format&fit=crop", // B&W Couple Fashion
  "https://images.unsplash.com/photo-1500917293891-ef795e70e1f6?q=80&w=2070&auto=format&fit=crop", // Editorial Couple
  "https://images.unsplash.com/photo-1485230946019-4d2bd423980d?q=80&w=2070&auto=format&fit=crop", // Intimate Close up
  "https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?q=80&w=1964&auto=format&fit=crop", // Artistic Portrait
  "https://images.unsplash.com/photo-1581338834647-b0fb40704e21?q=80&w=1974&auto=format&fit=crop", // Moody Fashion
  "https://images.unsplash.com/photo-1516575334481-f85287c2c81d?q=80&w=1974&auto=format&fit=crop", // Shadow Play
  "https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=1976&auto=format&fit=crop", // Emotional
  "https://images.unsplash.com/photo-1507114845806-0347f6150324?q=80&w=1974&auto=format&fit=crop", // Classic Style
  "https://images.unsplash.com/photo-1609505848912-b7c3b8b4beda?q=80&w=1965&auto=format&fit=crop", // Modern Love
  "https://images.unsplash.com/photo-1534353436294-0dbd4bdac845?q=80&w=1974&auto=format&fit=crop", // Cinematic
  "https://images.unsplash.com/photo-1616091216791-a5360b5fc78a?q=80&w=1990&auto=format&fit=crop", // Fashion Pose
  "https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e?q=80&w=1974&auto=format&fit=crop", // Model Vibe
];

const Hero: React.FC = () => {
  const [activeImage, setActiveImage] = useState(0);
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  // Track last mouse position to calculate distance
  const lastMousePos = useRef({ x: 0, y: 0 });

  // Wide visibility mask (550px radius)
  const maskImage = useMotionTemplate`radial-gradient(circle 550px at ${mouseX}px ${mouseY}px, black 45%, transparent 100%)`;
  const webkitMaskImage = useMotionTemplate`radial-gradient(circle 550px at ${mouseX}px ${mouseY}px, black 45%, transparent 100%)`;

  // Preload images
  useEffect(() => {
    HERO_IMAGES.forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

  const handleMouseMove = (e: React.MouseEvent) => {
    const { clientX, clientY } = e;

    // Update mask position
    mouseX.set(clientX);
    mouseY.set(clientY);

    // Calculate distance from last swap position
    const diffX = Math.abs(clientX - lastMousePos.current.x);
    const diffY = Math.abs(clientY - lastMousePos.current.y);
    const distance = Math.sqrt(diffX * diffX + diffY * diffY);

    // Swap image every ~50px of movement
    if (distance > 50) {
      setActiveImage((prev) => (prev + 1) % HERO_IMAGES.length);
      lastMousePos.current = { x: clientX, y: clientY };
    }
  };

  const scrollToNext = () => {
    const nextSection = document.getElementById('isoworld');
    if (nextSection) {
      nextSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section 
      className="relative h-screen w-full flex items-center justify-center overflow-hidden bg-black cursor-none"
      onMouseMove={handleMouseMove}
    >
      {/* Background Layer (Hidden by default, revealed by mask) */}
      <motion.div 
        className="absolute inset-0 z-0 bg-black"
        style={{
          maskImage,
          WebkitMaskImage: webkitMaskImage, // For Safari/Chrome
        }}
      >
        {HERO_IMAGES.map((src, index) => (
          <div
            key={index}
            // REMOVED transition-opacity and duration classes.
            // Using direct opacity switch for instant "hard cut" to avoid black blinking.
            className={`absolute inset-0 w-full h-full ${
              activeImage === index ? 'opacity-100' : 'opacity-0'
            }`}
          >
             <img
              src={src}
              alt="Hero Background"
              className="w-full h-full object-cover"
              style={{ filter: 'brightness(0.7) contrast(1.1) grayscale(0.2)' }}
            />
          </div>
        ))}
      </motion.div>

      {/* Main Content Layer */}
      <div className="container mx-auto px-6 z-20 relative text-center pointer-events-none mix-blend-difference">
        <div className="flex flex-col items-center justify-center h-full">
          {/* Main Title - ONLY COLLECTIVE */}
          <div className="relative">
            <div className="overflow-hidden">
              <motion.h1 
                initial={{ y: 100, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ duration: 1.2, ease: [0.22, 1, 0.36, 1] }}
                className="text-[12vw] md:text-[13vw] font-extrabold tracking-tighter leading-none text-white"
              >
                COLLECTIVE
              </motion.h1>
            </div>
          </div>

          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 1.5, duration: 1 }}
            className="mt-16 max-w-2xl mx-auto"
          >
            <p className="text-sm md:text-lg text-gray-300 font-medium tracking-widest uppercase flex items-center gap-4 justify-center">
              <span className="w-12 h-[1px] bg-gray-500"></span>
              Explore the unseen
              <span className="w-12 h-[1px] bg-gray-500"></span>
            </p>
          </motion.div>
        </div>
      </div>

      {/* Custom Scroll Indicator */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 2.0, duration: 1 }}
        className="absolute bottom-12 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center cursor-pointer pointer-events-auto group"
        onClick={scrollToNext}
      >
        <div className="w-[1px] h-[60px] bg-white/20 relative overflow-hidden group-hover:h-[80px] transition-all duration-300">
           <motion.div 
             animate={{ y: [-60, 60] }}
             transition={{ duration: 1.5, repeat: Infinity, ease: "linear" }}
             className="absolute top-0 left-0 w-full h-[30%] bg-[#FFB800]"
