interface HeaderProps {
  onAboutClick: () => void;
}

const Header: React.FC<HeaderProps> = ({ onAboutClick }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleNavClick = (item: typeof navItems[0], e: React.MouseEvent) => {
    if (item.label === 'ABOUT') {
      e.preventDefault();
      onAboutClick();
      setIsMenuOpen(false);
    }
    // Else let default href behavior happen
  };

  return (
    <>
      <header 
        className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
          isScrolled ? 'bg-black/90 backdrop-blur-md py-4 border-b border-white/10' : 'bg-transparent py-8'
        }`}
      >
        <div className="container mx-auto px-6 flex justify-between items-center">
          {/* Logo Section - Static Layout with Color Reveal Interaction */}
          <a href="#" className="flex items-center gap-2 z-50 relative group cursor-pointer select-none">
            {/* NADAUN: Always White */}
            <span className="text-2xl md:text-3xl font-extrabold text-white leading-none tracking-tight">
              NADAUN
            </span>

            {/* COLLECTIVE: White -> Gradient Reveal */}
