              {/* Base Layer: White */}
              <span className="text-2xl md:text-3xl font-light text-white leading-none tracking-tight transition-opacity duration-300 group-hover:opacity-0">
                COLLECTIVE
              </span>
              {/* Hover Layer: Gradient Key Color */}
              <span className="absolute inset-0 text-2xl md:text-3xl font-light text-transparent bg-clip-text bg-gradient-to-r from-[#FFB800] to-[#FF5E00] leading-none tracking-tight opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                COLLECTIVE
              </span>
            </div>
          </a>

          {/* Desktop Nav - Increased size and adjusted weight */}
          <nav className="hidden md:flex items-center space-x-12">
            {navItems.map((item) => (
              <a 
                key={item.label} 
                href={item.href}
                onClick={(e) => handleNavClick(item, e)}
                className="text-lg font-bold tracking-tight hover:text-[#FFB800] transition-colors relative group cursor-pointer"
              >
                {item.label}
                <span className="absolute -bottom-2 left-0 w-full h-[2px] bg-[#FFB800] scale-x-0 group-hover:scale-x-100 transition-transform origin-right group-hover:origin-left duration-300"></span>
