import Insights from './components/Insights';
import Footer from './components/Footer';
import AboutOverlay from './components/AboutOverlay'; // Import new overlay
import { motion, useScroll, useSpring } from 'framer-motion';

const App: React.FC = () => {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isAboutOpen, setIsAboutOpen] = useState(false); // State for About Overlay

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return (
    <div className="bg-black min-h-screen text-white selection:bg-[#FFB800] selection:text-black cursor-none">
      {/* Progress Bar */}
      <motion.div
        className="fixed top-0 left-0 right-0 h-1 bg-[#FFB800] origin-left z-[60]"
        style={{ scaleX }}
      />

      {/* Custom Cursor */}
      <div 
        className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
        style={{ 
          left: mousePosition.x, 
          top: mousePosition.y,
          transition: 'width 0.2s, height 0.2s',
        }}
      />

      {/* Header with About Click Handler */}
      <Header onAboutClick={() => setIsAboutOpen(true)} />

      {/* About Overlay */}
      <AboutOverlay isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} />

      <main>
        <Hero />
        <IsoWorld />
        {/* Removed <About /> section from main flow */}
        <Business />
        <Clients />
        <Work />
        <Insights />
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Html, Text, useCursor, Environment, ContactShadows, Float } from '@react-three/drei';
import * as THREE from 'three';
import { motion } from 'framer-motion-3d'; // Note: Standard framer-motion works with HTML, for 3D we usually use springs or simple lerp
import { SpringValue, useSpring, animated } from '@react-spring/three';

// --- DATA CONFIGURATION ---
const UNIVERSE_DATA = [
  { 
    id: 'space', 
    title: 'NADAUN SPACE', 
    subtitle: 'INFRA SOLUTION',
    desc: '모든 창작의 시작, 압도적 기술력의 인프라',
    url: 'https://rainbowshop.imweb.me/',
    color: '#00C2FF', // Cyan
    position: [-4.5, 0, 0] as [number, number, number],
    height: 3.5
  },
  { 
    id: 'studio', 
    title: 'NADAUN STUDIO', 
    subtitle: 'VISUAL MASTERPIECE',
    desc: '찰나를 영원으로 기록하는 비주얼 디렉팅',
    url: 'https://nadaun.framer.website/',
    color: '#FFB800', // Gold
    position: [-1.5, 0, 1.5] as [number, number, number],
    height: 4.5
  },
  { 
    id: 'project', 
    title: 'NADAUN PROJECT', 
    subtitle: 'MARKETING ACCELERATOR',
    desc: '시장을 뒤흔드는 압도적 퍼포먼스',
    url: '', // Coming Soon
    color: '#FF4D4D', // Red
    position: [1.5, 0, 0] as [number, number, number],
    height: 4.0
  },
  { 
    id: 'agency', 
    title: 'NAN AGENCY', 
    subtitle: 'FUTURE ENTERTAINMENT',
    desc: '뉴미디어 시대의 아이콘을 육성',
    url: 'https://nanofficial.imweb.me/',
    color: '#9D4DFF', // Purple
    position: [4.5, 0, 1.5] as [number, number, number],
    height: 3.8
  }
];

// --- 3D COMPONENTS ---

const Building = ({ data }: { data: typeof UNIVERSE_DATA[0] }) => {
  const [hovered, setHovered] = useState(false);
  const meshRef = useRef<THREE.Mesh>(null);

  // Change cursor on hover
  useCursor(hovered);

  const { scale, color, lift } = useSpring({
    scale: hovered ? 1.1 : 1,
    lift: hovered ? 0.5 : 0,
    color: hovered ? data.color : '#444',
    config: { mass: 1, tension: 280, friction: 60 }
  });

  const handleClick = () => {
    if (data.url) {
      window.open(data.url, '_blank');
    } else {
      alert("NADAUN PROJECT site is Coming Soon.");
    }
  };

  useFrame((state) => {
    if (meshRef.current) {
      // Subtle breathing animation
      meshRef.current.rotation.y += 0.002;
    }
  });

  return (
    <group position={data.position}>
      <Float speed={2} rotationIntensity={0.1} floatIntensity={0.2}>
        <animated.mesh
          ref={meshRef}
          position-y={lift}
          scale={scale}
          onClick={handleClick}
          onPointerOver={() => setHovered(true)}
          onPointerOut={() => setHovered(false)}
        >
          {/* Building Shape: Tall Box */}
          <boxGeometry args={[2, data.height, 2]} />
          <animated.meshPhysicalMaterial 
            color={color}
            metalness={0.8}
            roughness={0.2}
            clearcoat={1}
            transparent
            opacity={0.9}
            emissive={data.color}
            emissiveIntensity={hovered ? 0.5 : 0.1}
          />

          {/* Wireframe Edge for Tech feel */}
          <lineSegments>
            <edgesGeometry args={[new THREE.BoxGeometry(2, data.height, 2)]} />
            <meshBasicMaterial color={data.color} transparent opacity={0.3} />
          </lineSegments>
        </animated.mesh>
      </Float>

      {/* Floating HTML Label */}
      <Html position={[0, data.height / 2 + 1.5, 0]} center distanceFactor={12}>
        <div 
          className={`pointer-events-none transition-all duration-300 flex flex-col items-center text-center w-[300px] ${hovered ? 'scale-110 opacity-100 z-50' : 'scale-100 opacity-70 z-0'}`}
        >
          <div className="bg-black/80 backdrop-blur-md border border-white/20 p-4 rounded-lg shadow-2xl">
            <h3 
              className="text-xl font-bold tracking-tight mb-1"
              style={{ color: data.color }}
            >
              {data.title}
            </h3>
            <p className="text-[10px] font-bold tracking-[0.2em] text-gray-400 mb-2 uppercase">
              {data.subtitle}
            </p>
            <div className={`h-[1px] w-full bg-gradient-to-r from-transparent via-${data.color} to-transparent mb-2 opacity-50`}></div>
            <p className="text-xs text-gray-300 font-light leading-relaxed whitespace-pre-line">
              {data.desc}
            </p>
            {hovered && (
               <div className="mt-3 text-[10px] uppercase tracking-widest text-white bg-white/10 py-1 px-3 rounded-full border border-white/10">
                 {data.url ? 'Click to Enter' : 'Coming Soon'}
               </div>
            )}
          </div>
          {/* Connector Line */}
          <div className="w-[1px] h-8 bg-gradient-to-b from-white/50 to-transparent"></div>
        </div>
      </Html>

      {/* Floor Shadow */}
      <ContactShadows opacity={0.6} scale={10} blur={2} far={4} color={data.color} />
    </group>
  );
};

const Scene = () => {
  return (
    <>
      <ambientLight intensity={0.5} />
      <pointLight position={[10, 10, 10]} intensity={1} />
      <spotLight position={[-10, 20, -10]} angle={0.3} penumbra={1} intensity={2} color="#4444ff" />

      {/* Environment Reflection */}
      <Environment preset="city" />

      <group position={[0, -1, 0]} rotation={[0, -Math.PI / 6, 0]}>
        {UNIVERSE_DATA.map((item) => (
          <Building key={item.id} data={item} />
        ))}
      </group>
    </>
  );
};

