}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  const [isVisible, setIsVisible] = useState(true);

  useEffect(() => {
    // Sequence duration matches the animation definition below
    const timer = setTimeout(() => {
      setIsVisible(false);
      onComplete();
    }, 2500); // Total duration before unmounting

    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          className="fixed inset-0 z-[9999] flex items-center justify-center bg-black overflow-hidden"
          exit={{ opacity: 0 }}
          transition={{ duration: 0.5 }}
        >
          <motion.div
            className="relative flex items-center justify-center"
          >
            {/* The Point */}
            <motion.div
              className="w-2 h-2 bg-[#FFB800] rounded-full shadow-[0_0_20px_#FFB800]"
              initial={{ scale: 0, opacity: 0 }}
              animate={{
                scale: [0, 1.5, 1, 150], // Enter -> Pulse -> Anticipate -> Explode
                opacity: [0, 1, 1, 0], // Fade out at the very end of expansion
              }}
              transition={{
                duration: 2.2,
                times: [0, 0.3, 0.5, 1], // Timing of keyframes
                ease: [0.22, 1, 0.36, 1], // Custom bezier for cinematic feel
              }}
