            {/* Optional: Subtle white flash ring accompanying the explosion */}
            <motion.div 
               className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-full h-full border border-white/20 rounded-full"
               initial={{ width: 0, height: 0, opacity: 0 }}
