const HERO_IMAGES = [
  "https://images.unsplash.com/photo-1621784563330-caee0b138a00?q=80&w=2070&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1500917293891-ef795e70e1f6?q=80&w=2070&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?q=80&w=1964&auto=format&fit=crop",
];

const Hero: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"]
  });

  // --- SCROLL MAPPING ---
  // 1. Point Animation (0% - 15%)
  // Scale up from 1 to very large, then disappear
  const pointScale = useTransform(scrollYProgress, [0, 0.1], [1, 0.5]); // Shrink (Anticipation)
  const pointOpacity = useTransform(scrollYProgress, [0.1, 0.15], [1, 0]); // Fade out on explosion

  // 2. Explosion / Mask Reveal (10% - 30%)
  // The mask circle expands to reveal the background
  const maskSize = useTransform(scrollYProgress, [0.1, 0.3], [0, 200]); // Percentage size
  const maskImage = useMotionTemplate`radial-gradient(circle ${maskSize}vmax at center, black 100%, transparent 100%)`;

  // 3. Header Trigger (Passed via context or effectively managed by scroll position in App, but visually we handle the reveal here)
  // We don't animate the header directly here, but we create the space for it.

  // 4. Text Reveal (30% - 60%)
  // Dissolve in COLLECTIVE
  const textOpacity = useTransform(scrollYProgress, [0.3, 0.5], [0, 1]);
  const textBlur = useTransform(scrollYProgress, [0.3, 0.5], [20, 0]); // Blur effect for dissolve

  // 5. Fade out Hero to next section (85% - 100%)
  const sectionOpacity = useTransform(scrollYProgress, [0.85, 1], [1, 0]);

  // Image Cycling Logic
  const [activeImage, setActiveImage] = useState(0);
  useEffect(() => {
    const interval = setInterval(() => {
      setActiveImage((prev) => (prev + 1) % HERO_IMAGES.length);
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <section 
      ref={containerRef} 
      className="relative h-[400vh] bg-black" // Very tall to allow for scroll/drag interaction
    >
      <div className="sticky top-0 h-screen w-full overflow-hidden flex items-center justify-center">

        {/* BACKGROUND LAYER (Revealed by Mask) */}
        <motion.div 
          className="absolute inset-0 z-0 bg-black"
          style={{
            opacity: sectionOpacity,
            maskImage: maskImage,
            WebkitMaskImage: maskImage, // For Safari
          }}
        >
          {HERO_IMAGES.map((src, index) => (
            <div
              key={index}
              className={`absolute inset-0 w-full h-full transition-opacity duration-1000 ${
                activeImage === index ? 'opacity-100' : 'opacity-0'
              }`}
            >
               <img
                src={src}
                alt="Hero Background"
                className="w-full h-full object-cover"
                style={{ filter: 'brightness(0.6) contrast(1.1)' }}
              />
            </div>
          ))}
        </motion.div>

        {/* INTRO POINT LAYER */}
        <motion.div 
          className="absolute z-20 pointer-events-none"
          style={{ opacity: pointOpacity }}
        >
           <motion.div 
              className="w-3 h-3 bg-[#FFB800] rounded-full shadow-[0_0_30px_#FFB800]"
              style={{ scale: pointScale }}
           />
           <div className="absolute top-8 left-1/2 -translate-x-1/2 text-white/30 text-xs tracking-widest uppercase whitespace-nowrap">
              Scroll / Drag to Enter
           </div>
        </motion.div>

        {/* MAIN TEXT LAYER */}
        <motion.div 
          className="z-30 text-center mix-blend-difference"
          style={{ 
            opacity: textOpacity, 
            filter: useMotionTemplate`blur(${textBlur}px)` 
          }}
        >
          <h1 className="text-[15vw] font-extrabold tracking-tighter leading-none text-white">
            COLLECTIVE
          </h1>

          <div className="mt-8 flex items-center justify-center gap-4">
             <span className="h-[1px] w-12 bg-white/50"></span>
             <p className="text-white/70 tracking-[0.3em] uppercase text-sm">Beyond Imagination</p>
             <span className="h-[1px] w-12 bg-white/50"></span>
          </div>
        </motion.div>

        {/* Scroll Indicator (Shows up later) */}
        <motion.div 
           className="absolute bottom-10 left-1/2 -translate-x-1/2 text-white/50 text-xs tracking-widest uppercase"
           style={{ opacity: textOpacity }}
        >
          Keep Scrolling
        </motion.div>

      </div>
    </section>
  );
};

export default Hero;

import React, { useEffect, useState } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import IsoWorld from './components/IsoWorld';
import Business from './components/Business';
import Clients from './components/Clients';
import Work from './components/Work';
import Insights from './components/Insights';
import Footer from './components/Footer';
import AboutOverlay from './components/AboutOverlay';
import { motion, useScroll, useSpring } from 'framer-motion';

const App: React.FC = () => {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [showHeader, setShowHeader] = useState(false);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    const handleScroll = () => {
      // Show header after the intro "Explosion" which happens around 10-15% of the total page height 
      // OR specifically after the Hero's first phase. 
      // Since Hero is 400vh, 10% is quite a bit. Let's say when we scroll past 100px.
      // Better yet, based on the prompt "Drag then header appears", let's trigger it early.
      if (window.scrollY > 100) {
        setShowHeader(true);
      } else {
        setShowHeader(false);
      }
    };

    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  return (
    <div className="bg-black min-h-screen text-white selection:bg-[#FFB800] selection:text-black cursor-none">

      {/* Progress Bar */}
      <motion.div
        className="fixed top-0 left-0 right-0 h-1 bg-[#FFB800] origin-left z-[60]"
        style={{ scaleX }}
      />

      {/* Custom Cursor */}
      <div 
        className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
        style={{ 
          left: mousePosition.x, 
          top: mousePosition.y,
          transition: 'width 0.2s, height 0.2s',
        }}
      />

      {/* Header controlled by Scroll */}
      <Header onAboutClick={() => setIsAboutOpen(true)} show={showHeader} />

      {/* About Overlay */}
      <AboutOverlay isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} />

      <main>
        {/* Hero now handles the Intro sequence via scroll */}
        <Hero />
        <IsoWorld />
        <Business />
        <Clients />
        <Work />
        <Insights />
      </main>

      <Footer />
    </div>
  );
};

export default App;

