const Building = ({ data }: { data: typeof UNIVERSE_DATA[0] }) => {
  const [hovered, setHovered] = useState(false);
  const meshRef = useRef<THREE.Mesh>(null);

  // Change cursor on hover
  useCursor(hovered);

  const { scale, color, lift } = useSpring({
    scale: hovered ? 1.1 : 1,
    lift: hovered ? 0.5 : 0,
    color: hovered ? data.color : '#444',
    config: { mass: 1, tension: 280, friction: 60 }
  });

  const handleClick = () => {
    if (data.url) {
      window.open(data.url, '_blank');
    } else {
      alert(`${data.title} site is Coming Soon.`);
    }
  };

  useFrame((state) => {
    if (meshRef.current) {
      meshRef.current.rotation.y += 0.002;
    }
  });

  const boxGeometry = useMemo(() => new THREE.BoxGeometry(2, data.height, 2), [data.height]);

  return (
    <group position={data.position}>
      <Float speed={2} rotationIntensity={0.1} floatIntensity={0.2}>
        <animated.mesh
          ref={meshRef}
          position-y={lift}
          scale={scale}
          onClick={handleClick}
          onPointerOver={() => setHovered(true)}
          onPointerOut={() => setHovered(false)}
        >
          <boxGeometry args={[2, data.height, 2]} />
          <animated.meshPhysicalMaterial 
            color={color}
            metalness={0.8}
            roughness={0.2}
            clearcoat={1}
            transparent
            opacity={0.9}
            emissive={data.color}
            emissiveIntensity={hovered ? 0.5 : 0.1}
          />
          <lineSegments>
            <edgesGeometry args={[boxGeometry]} />
            <meshBasicMaterial color={data.color} transparent opacity={0.3} />
          </lineSegments>
        </animated.mesh>
      </Float>

      {/* Adjusted label position to be slightly tighter to the building */}
      <Html position={[0, data.height / 2 + 1.8, 0]} center distanceFactor={15} style={{ pointerEvents: 'none' }}>
        <div 
          className={`transition-all duration-300 flex flex-col items-center text-center w-[280px] ${hovered ? 'scale-110 opacity-100 z-50' : 'scale-100 opacity-60 z-0'}`}
        >
          <div className="bg-black/90 backdrop-blur-md border border-white/10 p-4 rounded-lg shadow-2xl pointer-events-auto">
            <h3 
              className="text-lg font-bold tracking-tight mb-1"
