import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  const [phase, setPhase] = useState<'text' | 'slide' | 'done'>('text');

  useEffect(() => {
    // Phase 1: Text Reveal & Hold (Total 2s)
    const timer1 = setTimeout(() => {
      setPhase('slide');
    }, 2200);

    // Phase 2: Slide Up & Dot Move (Transition takes ~1.2s)
    const timer2 = setTimeout(() => {
      setPhase('done');
      onComplete();
    }, 3400);

    return () => {
      clearTimeout(timer1);
      clearTimeout(timer2);
    };
  }, [onComplete]);

  return (
    <AnimatePresence>
      {phase !== 'done' && (
        <div className="fixed inset-0 z-[100] pointer-events-none">
          {/* Black Background Curtain */}
          <motion.div
            initial={{ y: 0 }}
            animate={{ 
              y: phase === 'slide' ? '-100%' : 0,
              borderBottomLeftRadius: phase === 'slide' ? '50% 20%' : '0%',
              borderBottomRightRadius: phase === 'slide' ? '50% 20%' : '0%'
            }}
            transition={{ 
              duration: 1.2, 
              ease: [0.76, 0, 0.24, 1] // Custom bezier for dramatic slide
            }}
            className="absolute inset-0 bg-black flex items-center justify-center"
          >
            {/* Text Container */}
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: phase === 'text' ? 1 : 0 }}
              transition={{ duration: 0.5, delay: 0.2 }}
              className="text-center relative z-10"
            >
               <motion.div 
                 initial={{ y: 20, opacity: 0 }}
                 animate={{ y: 0, opacity: 1 }}
                 transition={{ duration: 0.8, ease: "easeOut" }}
                 className="flex flex-col items-center gap-4"
               >
                 <h1 className="text-4xl md:text-6xl font-extrabold tracking-tighter text-white">
                   NADAUN <span className="text-[#FFB800]">COLLECTIVE</span>
                 </h1>
                 <div className="w-12 h-1 bg-[#FFB800] mt-4" />
               </motion.div>
            </motion.div>
          </motion.div>

          {/* Yellow Dot Animation */}
          {/* This element sits ON TOP of the black curtain so it remains visible as the curtain slides up */}
          <motion.div
            initial={{ 
              top: "50%", 
              left: "50%", 
              x: "-50%", 
              y: "-50%", 
              width: "12px",
              height: "12px",
              borderRadius: "50%",
              backgroundColor: "#FFB800",
              boxShadow: "0 0 20px rgba(255, 184, 0, 0.5)"
            }}
            animate={{
              // Animation based on phase
              top: phase === 'slide' ? "53px" : "50%", // Approximate Header vertical center (py-8 + half height)
              left: phase === 'slide' ? "auto" : "50%",
              right: phase === 'slide' ? "145px" : "auto", // Approximate position of the dot inside the Contact button
              x: phase === 'slide' ? 0 : "-50%",
              y: phase === 'slide' ? 0 : "-50%",
              scale: phase === 'slide' ? 0.8 : [0, 1.2, 1], // Scale pulse on entry
              opacity: phase === 'slide' ? 0 : 1 // Fade out at the very end to seamlessly blend with header dot
            }}
            transition={{
              top: { duration: 1.2, ease: [0.76, 0, 0.24, 1] },
              right: { duration: 1.2, ease: [0.76, 0, 0.24, 1] },
              left: { duration: 1.2, ease: [0.76, 0, 0.24, 1] },
              x: { duration: 1.2, ease: [0.76, 0, 0.24, 1] },
              y: { duration: 1.2, ease: [0.76, 0, 0.24, 1] },
              scale: phase === 'text' ? { duration: 0.8, times: [0, 0.6, 1] } : { duration: 1.2 },
              opacity: { delay: 1.1, duration: 0.1 } // Quick fade out right when it hits the target
            }}
            className="fixed z-[101]"
          />
        </div>
      )}
    </AnimatePresence>
  );
};

export default Intro;

