      {/* About Overlay */}
      <AboutOverlay isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} />

      <main>
        {/* Pass intro state to Hero so it can animate the text in when ready */}
        <Hero startAnimation={introFinished} />
        <IsoWorld />
        <Business />
        <Clients />
        <Work />
        <Insights />
      </main>

      <Footer />
    </div>
  );
};

