import React, { useEffect, useState } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import IsoWorld from './components/IsoWorld';
import Business from './components/Business';
import Clients from './components/Clients';
import Work from './components/Work';
import Insights from './components/Insights';
import Footer from './components/Footer';
import AboutOverlay from './components/AboutOverlay';
import Intro from './components/Intro';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';

const App: React.FC = () => {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isAboutOpen, setIsAboutOpen] = useState(false);
  const [introFinished, setIntroFinished] = useState(false);

  // Header is always mounted to receive layout animations
  const [showHeader, setShowHeader] = useState(true);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    window.addEventListener("mousemove", handleMouseMove);

    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
    };
  }, []);

  return (
    <div className="bg-black min-h-screen text-white selection:bg-[#FFB800] selection:text-black cursor-none">

      {/* Intro Animation - Controls layoutId elements initially */}
      <AnimatePresence mode="sync">
        {!introFinished && (
          <Intro onComplete={() => setIntroFinished(true)} />
        )}
      </AnimatePresence>

      {/* Progress Bar */}
      {introFinished && (
        <motion.div
          className="fixed top-0 left-0 right-0 h-1 bg-[#FFB800] origin-left z-[60]"
          style={{ scaleX }}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5 }}
        />
      )}

      {/* Custom Cursor */}
      <div 
        className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
        style={{ 
          left: mousePosition.x, 
          top: mousePosition.y,
          transition: 'width 0.2s, height 0.2s',
        }}
      />

      {/* Header - Receives layoutId elements when Intro unmounts */}
      <Header 
        onAboutClick={() => setIsAboutOpen(true)} 
        show={showHeader} 
        introFinished={introFinished}
      />

      {/* About Overlay */}
      <AboutOverlay isOpen={isAboutOpen} onClose={() => setIsAboutOpen(false)} />

      <main>
        {/* Pass intro state to Hero so it can animate the text in when ready */}
        <Hero startAnimation={introFinished} />
        <IsoWorld />
        <Business />
        <Clients />
        <Work />
        <Insights />
      </main>

      <Footer />
    </div>
  );
};

export default App;

import React, { useEffect } from 'react';
import { motion } from 'framer-motion';

interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  useEffect(() => {
    // Sequence:
    // 0s: Start
    // 0.5s: Elements appear
    // 2.0s: Trigger complete (which unmounts Intro and triggers layoutId transition to Header)
    const timer = setTimeout(() => {
      onComplete();
    }, 2500);

    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <motion.div
      className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center pointer-events-none"
      initial={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.8, delay: 0.2 }} // Fade out background AFTER elements start moving
    >
      <div className="relative flex flex-col items-center justify-center">
        {/* The Text that moves to Logo */}
        <div className="overflow-hidden relative z-10">
          <motion.span
            layoutId="logo-collective"
            className="text-4xl md:text-7xl font-light text-white tracking-tight inline-block"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: "easeOut" }}
          >
            COLLECTIVE
          </motion.span>
        </div>

        {/* The Dot that moves to Contact Button */}
        <motion.div
          layoutId="contact-dot"
          className="absolute"
          initial={{ 
            width: "0px",
            height: "0px",
            opacity: 0,
            top: "50%",
            left: "50%",
            x: "-50%",
            y: "-50%"
          }}
          animate={{ 
            width: "24px", 
            height: "24px",
            opacity: 1,
            top: "50%", // Keep centered relative to parent for now
            y: 60 // Push down below text
          }}
          // Pulse animation before moving
          whileInView={{
             scale: [1, 1.5, 1],
             transition: { delay: 1.0, duration: 0.6 }
          }}
          transition={{ duration: 0.8, ease: "easeOut" }}
          style={{ 
            borderRadius: "50%", 
            backgroundColor: "#FFB800",
            boxShadow: "0 0 30px rgba(255, 184, 0, 0.6)"
          }}
        />
      </div>
    </motion.div>
  );
};

export default Intro;

