        </div>

        {/* The Dot that expands to full screen then moves to Contact Button */}
        <motion.div
          layoutId="contact-dot"
          className="absolute bg-[#FFB800] rounded-full"
          initial={{ 
            width: "20px",
            height: "20px",
            bottom: "-100px", // Start below screen
            borderRadius: "50%"
          }}
          animate={{ 
            bottom: ["-100px", "50%", "50%"], // Rise up, then stay centered
            y: [0, 150, 0], // Slight bounce adjustment
            scale: [1, 1, 150], // Explode to fill screen at the end
          }}
          transition={{
            duration: 1.8,
            times: [0, 0.6, 1], // Timing of keyframes
            ease: [0.76, 0, 0.24, 1]
          }}
          style={{
            zIndex: 20 // Higher than text to cover it
          }}
        />
      </div>
    </div>
  );
};

