import React, { useState, useEffect, useRef } from 'react';
import { motion, useMotionValue, useMotionTemplate } from 'framer-motion';

// High-quality creative studio images
const HERO_IMAGES = [
  "https://images.unsplash.com/photo-1621784563330-caee0b138a00?q=80&w=2070&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1500917293891-ef795e70e1f6?q=80&w=2070&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1531746020798-e6953c6e8e04?q=80&w=1964&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1581338834647-b0fb40704e21?q=80&w=1974&auto=format&fit=crop", 
  "https://images.unsplash.com/photo-1516575334481-f85287c2c81d?q=80&w=1974&auto=format&fit=crop",
];

interface HeroProps {
  startAnimation?: boolean;
}

const Hero: React.FC<HeroProps> = ({ startAnimation = true }) => {
  const [activeImage, setActiveImage] = useState(0);
  const mouseX = useMotionValue(0);
  const mouseY = useMotionValue(0);

  const lastMousePos = useRef({ x: 0, y: 0 });

  const maskImage = useMotionTemplate`radial-gradient(circle 500px at ${mouseX}px ${mouseY}px, black 50%, transparent 100%)`;
  const webkitMaskImage = useMotionTemplate`radial-gradient(circle 500px at ${mouseX}px ${mouseY}px, black 50%, transparent 100%)`;

  useEffect(() => {
    HERO_IMAGES.forEach((src) => {
      const img = new Image();
      img.src = src;
    });
  }, []);

  const handleMouseMove = (e: React.MouseEvent) => {
    const { clientX, clientY } = e;
    mouseX.set(clientX);
    mouseY.set(clientY);

    const diffX = Math.abs(clientX - lastMousePos.current.x);
    const diffY = Math.abs(clientY - lastMousePos.current.y);
    const distance = Math.sqrt(diffX * diffX + diffY * diffY);

    if (distance > 200) {
      setActiveImage((prev) => (prev + 1) % HERO_IMAGES.length);
      lastMousePos.current = { x: clientX, y: clientY };
    }
  };

  const scrollToNext = () => {
    const nextSection = document.getElementById('isoworld');
    if (nextSection) {
      nextSection.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <section 
      className="relative h-screen w-full flex items-center justify-center overflow-hidden bg-black cursor-none"
      onMouseMove={handleMouseMove}
    >
      {/* Background Layer */}
      <motion.div 
        className="absolute inset-0 z-0 bg-black"
        style={{
          maskImage,
          WebkitMaskImage: webkitMaskImage,
        }}
      >
        {HERO_IMAGES.map((src, index) => (
          <div
            key={index}
            className={`absolute inset-0 w-full h-full ${
              activeImage === index ? 'opacity-100' : 'opacity-0'
            }`}
          >
             <img
              src={src}
              alt="Hero Background"
              className="w-full h-full object-cover"
              style={{ filter: 'brightness(0.7) contrast(1.1) grayscale(0.2)' }}
            />
          </div>
        ))}
      </motion.div>

      {/* Main Content Layer */}
      <div className="container mx-auto px-6 z-20 relative text-center pointer-events-none mix-blend-difference">
        <div className="flex flex-col items-center justify-center h-full">
          {/* Main Title - This receives the Intro text */}
          <div className="relative overflow-visible">
             <motion.h1 
                layoutId="hero-title-text"
                transition={{ duration: 1.2, ease: [0.76, 0, 0.24, 1] }}
                className="text-[12vw] md:text-[13vw] font-extrabold tracking-tighter leading-none text-white"
              >
                COLLECTIVE
              </motion.h1>
          </div>

          <motion.div 
            initial={{ opacity: 0 }}
            animate={startAnimation ? { opacity: 1 } : { opacity: 0 }}
            transition={{ delay: 1.0, duration: 1 }}
            className="mt-16 max-w-2xl mx-auto"
          >
            <p className="text-sm md:text-lg text-gray-300 font-medium tracking-widest uppercase flex items-center gap-4 justify-center">
              <span className="w-12 h-[1px] bg-gray-500"></span>
              Explore the unseen
              <span className="w-12 h-[1px] bg-gray-500"></span>
            </p>
          </motion.div>
        </div>
      </div>

      {/* Custom Scroll Indicator */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={startAnimation ? { opacity: 1 } : { opacity: 0 }}
        transition={{ delay: 1.5, duration: 1 }}
        className="absolute bottom-12 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center cursor-pointer pointer-events-auto group"
        onClick={scrollToNext}
      >
        <div className="w-[1px] h-[60px] bg-white/20 relative overflow-hidden group-hover:h-[80px] transition-all duration-300">
           <motion.div 
             animate={{ y: [-60, 60] }}
             transition={{ duration: 1.5, repeat: Infinity, ease: "linear" }}
             className="absolute top-0 left-0 w-full h-[30%] bg-[#FFB800]"
           />
        </div>
      </motion.div>
    </section>
  );
};

export default Hero;

import React, { useEffect } from 'react';
import { motion } from 'framer-motion';

interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  useEffect(() => {
    // Sequence:
    // 0.0s - 0.6s: Dot rises from bottom to center
    // 0.6s - 1.4s: Expands to full screen (Covers text)
    // 1.4s - 1.9s: Holds full screen
    // 1.9s - 2.7s: Shrinks back to center circle (Reveals text)
    // 2.8s: Unmount triggers 'layoutId' transition -> Dot flies to Header Contact, Text syncs to Hero
    const timer = setTimeout(() => {
      onComplete();
    }, 2800);

    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center pointer-events-none">
      {/* 1. Black Background - Fades out as the sequence finishes */}
      <motion.div 
        className="absolute inset-0 bg-black"
        exit={{ opacity: 0, transition: { duration: 0.5 } }}
      />

      {/* 2. Text Container - z-10 (Behind yellow layer) */}
      <div className="absolute inset-0 flex items-center justify-center z-10">
        <motion.h1
          layoutId="hero-title-text"
          className="text-[12vw] md:text-[13vw] font-extrabold tracking-tighter leading-none text-white"
          initial={{ opacity: 0, scale: 0.8, y: 50 }}
          animate={{ opacity: 1, scale: 1, y: 0 }}
          transition={{ duration: 0.8, ease: "easeOut" }}
        >
          COLLECTIVE
        </motion.h1>
      </div>

      {/* 3. Yellow Element - z-20 (Covers text when full screen) */}
      <div className="absolute inset-0 flex items-center justify-center overflow-hidden z-20">
        <motion.div
          layoutId="yellow-intro-morph"
          initial={{ 
            width: "20px",
            height: "20px",
            borderRadius: "50%",
            y: 400, // Start from bottom
          }}
          animate={{ 
            y: [400, 0, 0, 0, 0], // Rise -> Stay -> Stay -> Stay -> Stay
            scale: [1, 1, 150, 150, 1], // Small -> Small -> Full -> Full -> Small
            borderRadius: ["50%", "50%", "0%", "0%", "50%"], // Circle -> Circle -> Rect -> Rect -> Circle
          }}
          transition={{
            duration: 2.7,
            times: [0, 0.2, 0.45, 0.7, 1], // Timing percentage points
            ease: [0.76, 0, 0.24, 1] // Custom bezier for premium feel
          }}
          className="bg-[#FFB800]"
        />
      </div>
    </div>
  );
};

