interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  useEffect(() => {
    // Sequence:
    // 0.0s - 0.6s: Dot rises, Text is VISIBLE.
    // 0.6s - 1.4s: Yellow expands (Covers Text).
    // 1.0s: Text opacity becomes 0 (Secretly hidden behind yellow).
    // 1.8s - 2.5s: Yellow shrinks back to dot. Background is Black. NO TEXT.
    // 2.6s: Trigger flight to Header.
    const timer = setTimeout(() => {
      onComplete();
    }, 2600);

    return () => clearTimeout(timer);
  }, [onComplete]);

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center pointer-events-none">
      {/* 1. Black Background */}
      <motion.div 
        className="absolute inset-0 bg-black"
        exit={{ opacity: 0, transition: { duration: 0.8, delay: 0.2 } }}
      />

      {/* 2. Text Container - VISIBLE AT START, GONE AFTER YELLOW COVERS IT */}
      <div className="absolute inset-0 flex items-center justify-center z-10">
        <motion.h1
          className="text-[12vw] md:text-[13vw] font-extrabold tracking-tighter leading-none text-white"
          initial={{ opacity: 0, scale: 0.8, y: 50 }}
          animate={{ opacity: [0, 1, 1, 0] }} // Fade In -> Hold -> Disappear
          transition={{ 
            duration: 1.5,
            times: [0, 0.2, 0.5, 0.8], // Gone by 0.8 * 1.5s = 1.2s (Before shrink starts)
            ease: "easeOut" 
          }}
        >
          COLLECTIVE
        </motion.h1>
      </div>

      {/* 3. Yellow Element - Covers text, then shrinks to dot */}
      <div className="absolute inset-0 flex items-center justify-center overflow-hidden z-20">
        <motion.div
          layoutId="yellow-intro-morph"
          initial={{ 
            width: "20px",
            height: "20px",
            borderRadius: "50%",
            y: 400, // Start from bottom
          }}
          animate={{ 
            y: [400, 0, 0, 0, 0], 
            scale: [1, 1, 150, 150, 1], 
            borderRadius: ["50%", "50%", "0%", "0%", "50%"],
          }}
          transition={{
            duration: 2.5,
            times: [0, 0.24, 0.56, 0.72, 1], 
            ease: [0.76, 0, 0.24, 1] 
          }}
          className="bg-[#FFB800]"
        />
      </div>
    </div>
  );
};

