import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  const [stage, setStage] = useState(0); 
  // 0: Dot
  // 1: Text Reveal (White)
  // 2: Yellow Wipe (Inversion)
  // 3: Lift Off

  useEffect(() => {
    // Sequence Timeline management
    const sequence = async () => {
      // Step 1: Dot hold briefly
      await new Promise(r => setTimeout(r, 200));
      setStage(1); // Text appears

      // Step 2: Hold text for reading
      await new Promise(r => setTimeout(r, 600)); 
      setStage(2); // Yellow Wipe Starts

      // Step 3: Wipe Duration (Fast Linear)
      await new Promise(r => setTimeout(r, 500));
      setStage(3); // Lift Off

      // Step 4: Cleanup
      setTimeout(onComplete, 600);
    };

    sequence();
  }, [onComplete]);

  return (
    <motion.div 
      className="fixed inset-0 z-[100] pointer-events-none flex flex-col font-manrope"
      initial={{ y: 0 }}
      animate={stage === 3 ? { y: "-100%" } : { y: 0 }}
      transition={{ duration: 0.5, ease: [0.76, 0, 0.24, 1] }} // Snappy lift
    >
      <div className="relative w-full h-full">

        {/* === LAYER 1: BASE (Black BG, White Text) === */}
        <div className="absolute inset-0 bg-black flex items-center justify-center overflow-hidden">

          {/* A. The Dot - Intro Element */}
          <AnimatePresence>
            {stage === 0 && (
              <motion.div
                className="absolute bg-white rounded-full z-20"
                initial={{ width: 0, height: 0 }}
                animate={{ width: 12, height: 12 }}
                exit={{ scale: 0, opacity: 0 }}
                transition={{ duration: 0.3 }}
              />
            )}
          </AnimatePresence>

          {/* B. The Text (White) - Base Layer */}
          <motion.div
            className="z-10 relative overflow-hidden"
            initial={{ opacity: 0, y: 40 }}
            animate={stage >= 1 ? { opacity: 1, y: 0 } : { opacity: 0, y: 40 }}
            transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1] }}
          >
             <h1 className="text-[13vw] font-extrabold tracking-tighter leading-none text-white select-none">
              COLLECTIVE
            </h1>
          </motion.div>
        </div>

        {/* === LAYER 2: OVERLAY (Yellow BG, Black Text) - The Mask === */}
        {/* We use clipPath to reveal this layer from bottom to top linearly */}
        <motion.div
          className="absolute inset-0 bg-[#FFB800] flex items-center justify-center overflow-hidden z-20"
          initial={{ clipPath: "inset(100% 0 0 0)" }} // Hidden at bottom
          animate={stage >= 2 ? { clipPath: "inset(0% 0 0 0)" } : { clipPath: "inset(100% 0 0 0)" }}
          transition={{ 
            duration: 0.5, 
            ease: "linear" // STRICT LINEAR WIPE as requested
          }}
        >
          {/* C. The Text (Black) - Matches Base Layer Position Exactly */}
          <div className="relative overflow-hidden">
            <h1 className="text-[13vw] font-extrabold tracking-tighter leading-none text-black select-none">
              COLLECTIVE
            </h1>
          </div>
        </motion.div>

      </div>
    </motion.div>
  );
};

