import React, { useEffect, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';

interface IntroProps {
  onComplete: () => void;
}

const Intro: React.FC<IntroProps> = ({ onComplete }) => {
  const [stage, setStage] = useState(0);

  useEffect(() => {
    // Timeline Sequence
    const sequence = async () => {
      // 1. Dot Appearance
      await new Promise(r => setTimeout(r, 100));
      setStage(1); // Dot Active

      // 2. Text Reveal (Dot disappears)
      await new Promise(r => setTimeout(r, 600)); 
      setStage(2); // Text Active

      // 3. Yellow Circle Expansion (Inversion)
      await new Promise(r => setTimeout(r, 800));
      setStage(3); // Yellow Expand

      // 4. Mask Dissolve (Aperture Reveal)
      // Wait for yellow expansion to finish approx 0.5s
      await new Promise(r => setTimeout(r, 600)); 
      setStage(4); // Mask Open (Dissolve)

      // 5. Cleanup
      setTimeout(onComplete, 600);
    };

    sequence();
  }, [onComplete]);

  return (
    <motion.div 
      className="fixed inset-0 z-[100] pointer-events-none flex flex-col font-manrope"
      // Instead of moving the whole container y: -100%, we use a mask to dissolve it
      animate={stage === 4 ? { 
        WebkitMaskSize: "300%", // Expand the hole
        maskSize: "300%"
      } : { 
        WebkitMaskSize: "0%", 
        maskSize: "0%"
      }}
      initial={{ 
        WebkitMaskImage: "radial-gradient(circle at center, transparent 0%, black 0%)",
        maskImage: "radial-gradient(circle at center, transparent 0%, black 0%)",
        WebkitMaskRepeat: "no-repeat",
        maskRepeat: "no-repeat",
        WebkitMaskPosition: "center",
        maskPosition: "center",
      }}
      style={{
        // The mask defines what is VISIBLE. 
        // We want to create a HOLE.
        // radial-gradient(circle, transparent X%, black X%)
        // As X increases, the transparent part (hole) grows.
        // Note: We animate the percentage or size via CSS variables or motion values.
        // Framer Motion 'animate' prop above handles maskSize if we set up the gradient correctly.
        // Let's use a simpler approach for the mask animation:
        WebkitMaskImage: "radial-gradient(circle at center, transparent 35%, black 36%)",
        maskImage: "radial-gradient(circle at center, transparent 35%, black 36%)",
        // Initially size is 0 (no hole, fully black visible). 
        // Animated to huge size (hole consumes screen).
      }}
      transition={{ duration: 0.5, ease: "circIn" }} // Accelerate into the reveal
    >
      <div className="relative w-full h-full bg-black">

        {/* === LAYER 1: BASE (Black BG, White Text) === */}
        <div className="absolute inset-0 flex items-center justify-center overflow-hidden">

          {/* A. The Dot */}
          <AnimatePresence>
            {stage === 1 && (
              <motion.div
                className="absolute bg-white rounded-full z-20"
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                exit={{ scale: 0, opacity: 0 }}
                transition={{ duration: 0.3, type: "spring", stiffness: 300, damping: 20 }}
                style={{ width: 16, height: 16 }}
              />
            )}
          </AnimatePresence>

          {/* B. The Text (White) */}
          <motion.div
            className="z-10 relative overflow-hidden"
            initial={{ opacity: 0, scale: 0.8 }}
            animate={stage >= 2 ? { opacity: 1, scale: 1 } : { opacity: 0, scale: 0.8 }}
            transition={{ duration: 0.5, ease: "easeOut" }}
          >
             <h1 className="text-[13vw] font-extrabold tracking-tighter leading-none text-white select-none">
              COLLECTIVE
            </h1>
          </motion.div>
        </div>

        {/* === LAYER 2: SHAPE MOTION (Yellow Circle Inversion) === */}
        <motion.div
          className="absolute inset-0 bg-[#FFB800] flex items-center justify-center overflow-hidden z-20"
          initial={{ clipPath: "circle(0% at 50% 50%)" }} 
          animate={stage >= 3 ? { clipPath: "circle(150% at 50% 50%)" } : { clipPath: "circle(0% at 50% 50%)" }}
          transition={{ 
            duration: 0.6, 
            ease: "linear" // Mechanical expansion
          }}
        >
          {/* C. The Text (Black) - Inverted */}
          <div className="relative overflow-hidden">
            <h1 className="text-[13vw] font-extrabold tracking-tighter leading-none text-black select-none">
              COLLECTIVE
            </h1>
          </div>
        </motion.div>

      </div>
    </motion.div>
  );
};

