// Graph Configuration
const CANVAS_SIZE = 2000; // Draggable area size
const CONNECTION_DISTANCE = 350; // Distance to draw lines between nodes

const Clients: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [hoveredNode, setHoveredNode] = useState<number | null>(null);

  // Generate random positions for nodes in a "Constellation" distribution
  const nodes = useMemo(() => {
    return CLIENT_LIST.map((client, index) => {
      // Create a more organic, centered scatter distribution
      const angle = (index / CLIENT_LIST.length) * Math.PI * 2 * 3; // Spiral
      const radius = 200 + (index * 25) + (Math.random() * 100); // Expanding outward
      const x = CANVAS_SIZE / 2 + Math.cos(angle) * radius * (Math.random() > 0.5 ? 1 : -1) * 0.8;
      const y = CANVAS_SIZE / 2 + Math.sin(angle) * radius * 0.8;

      return { ...client, x, y, id: index };
    });
  }, []);

  // Calculate lines (edges) between close nodes
  const edges = useMemo(() => {
    const lines: { from: number; to: number; distance: number }[] = [];
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < CONNECTION_DISTANCE) {
          lines.push({ from: i, to: j, distance });
        }
      }
    }
    return lines;
  }, [nodes]);

  return (
    <section className="relative w-full h-screen bg-[#050505] overflow-hidden cursor-grab active:cursor-grabbing border-t border-white/5">

      {/* Background Grid for Scale Reference */}
      <div 
        className="absolute inset-0 z-0 opacity-10 pointer-events-none" 
        style={{ 
          backgroundImage: 'radial-gradient(#333 1px, transparent 1px)', 
          backgroundSize: '40px 40px' 
        }} 
      />

      {/* Title Overlay (Fixed) */}
      <div className="absolute top-12 left-6 md:left-12 z-20 pointer-events-none">
        <h2 className="text-5xl md:text-7xl font-extrabold tracking-tighter text-white leading-none mb-2">
          OUR <br/> <span className="text-[#FFB800]">PARTNERS</span>
        </h2>
        <p className="text-sm text-gray-400 font-medium tracking-widest uppercase">
          Drag to explore the network
        </p>
      </div>

      {/* Draggable Universe */}
      <motion.div
        ref={containerRef}
        className="relative w-full h-full flex items-center justify-center"
        drag
        dragConstraints={{ left: -1000, right: 1000, top: -1000, bottom: 1000 }}
        dragElastic={0.1}
        dragTransition={{ bounceStiffness: 200, bounceDamping: 20 }}
      >
        <div 
          style={{ 
            width: CANVAS_SIZE, 
            height: CANVAS_SIZE, 
            position: 'absolute',
            left: `calc(50% - ${CANVAS_SIZE/2}px)`,
            top: `calc(50% - ${CANVAS_SIZE/2}px)`
          }}
        >
          {/* SVG Layer for Lines (Obsidian Connections) */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
            {edges.map((edge, i) => {
              const start = nodes[edge.from];
              const end = nodes[edge.to];
              const isConnectedToHover = hoveredNode === edge.from || hoveredNode === edge.to;

              return (
                <motion.line
                  key={`line-${i}`}
                  x1={start.x}
                  y1={start.y}
                  x2={end.x}
                  y2={end.y}
                  stroke={isConnectedToHover ? "#FFB800" : "#333"}
                  strokeWidth={isConnectedToHover ? 1.5 : 0.5}
                  initial={{ pathLength: 0, opacity: 0 }}
                  whileInView={{ pathLength: 1, opacity: isConnectedToHover ? 0.8 : 0.2 }}
                  viewport={{ once: true }}
                  transition={{ duration: 1.5, ease: "easeInOut" }}
                />
              );
            })}
          </svg>

          {/* Node Layer */}
          {nodes.map((node) => (
