          <span className="w-2 h-2 bg-[#FFB800] rounded-full animate-pulse"/>
          Drag to explore the constellation
        </p>
      </div>

      {/* Draggable Universe */}
      <motion.div
        ref={containerRef}
        className="relative w-full h-full flex items-center justify-center"
        drag
        dragConstraints={{ left: -1200, right: 1200, top: -1200, bottom: 1200 }}
        dragElastic={0.05}
        dragTransition={{ bounceStiffness: 100, bounceDamping: 10 }}
        whileTap={{ cursor: "grabbing" }}
      >
        <div 
          style={{ 
            width: CANVAS_SIZE, 
            height: CANVAS_SIZE, 
            position: 'absolute',
            left: `calc(50% - ${CANVAS_SIZE/2}px)`,
            top: `calc(50% - ${CANVAS_SIZE/2}px)`
          }}
        >
          {/* SVG Layer for Lines (Obsidian Connections) */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
            {edges.map((edge, i) => {
              const start = nodes[edge.from];
              const end = nodes[edge.to];
              const isConnectedToHover = hoveredNode === edge.from || hoveredNode === edge.to;

              return (
                <motion.line
                  key={`line-${i}`}
                  x1={start.x}
                  y1={start.y}
                  x2={end.x}
                  y2={end.y}
                  stroke={isConnectedToHover ? "#FFB800" : "#222"}
                  strokeWidth={isConnectedToHover ? 1.5 : 0.5}
                  initial={{ opacity: 0 }}
                  whileInView={{ opacity: isConnectedToHover ? 0.8 : 0.2 }}
                  viewport={{ once: true }}
                  transition={{ duration: 1 }}
                />
              );
            })}
          </svg>

          {/* Node Layer */}
          {nodes.map((node) => (
            <motion.div
              key={node.id}
              className="absolute group flex flex-col items-center justify-center text-center"
              style={{ 
                left: node.x, 
                top: node.y,
                transform: 'translate(-50%, -50%)',
                zIndex: hoveredNode === node.id ? 50 : 10
              }}
              onMouseEnter={() => setHoveredNode(node.id)}
              onMouseLeave={() => setHoveredNode(null)}
              initial={{ opacity: 0, scale: 0 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: Math.random() * 0.3 }}
            >
              {/* Dot */}
              <div 
                className={`w-2 h-2 rounded-full mb-4 transition-all duration-300 
                  ${hoveredNode === node.id ? 'bg-[#FFB800] scale-[2] shadow-[0_0_20px_rgba(255,184,0,0.8)]' : 'bg-gray-600'}`} 
              />

              {/* Text Label - High Visibility */}
              <div className={`transition-all duration-300 ${hoveredNode === node.id ? 'scale-110' : 'scale-100 opacity-60'}`}>
                <h3 className={`text-xl md:text-3xl font-extrabold tracking-tight whitespace-nowrap leading-none 
                  ${hoveredNode === node.id ? 'text-white' : 'text-gray-400'}`}>
                  {node.name}
                </h3>
                <span className={`text-[9px] md:text-[10px] font-bold tracking-[0.2em] uppercase block mt-2
                  ${hoveredNode === node.id ? 'text-[#FFB800]' : 'text-gray-600'}`}>
                  {node.category}
                </span>
              </div>
            </motion.div>
          ))}
