    window.addEventListener("mousemove", handleMouseMove);
    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
    };
  }, []);

  const handleNavClick = (id: string) => {
    setActiveOverlay(id);
  };

  const closeOverlay = () => {
    setActiveOverlay(null);
  };

  return (
    <div className="bg-black min-h-screen text-white selection:bg-[#FFB800] selection:text-black cursor-none">

      {/* Intro Animation Layer */}
      <AnimatePresence mode="sync">
        {!introFinished && (
          <Intro onComplete={() => setIntroFinished(true)} />
        )}
      </AnimatePresence>

      {/* Main Content */}
      <div className="relative z-0">
        <Header 
          onNavClick={handleNavClick}
          show={showHeader} 
          introFinished={introFinished}
        />

        {/* Progress Bar */}
        {introFinished && (
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-[#FFB800] origin-left z-[60]"
            style={{ scaleX }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5 }}
          />
        )}

        {/* Custom Cursor */}
        <div 
          className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
          style={{ 
            left: mousePosition.x, 
            top: mousePosition.y,
            transition: 'width 0.2s, height 0.2s',
          }}
        />

        {/* --- OVERLAYS --- */}
        <AboutOverlay isOpen={activeOverlay === 'about'} onClose={closeOverlay} />

        <Overlay isOpen={activeOverlay === 'business'} onClose={closeOverlay} title="Business Domain">
           <div className="pt-8">
             <Business />
           </div>
        </Overlay>

        <Overlay isOpen={activeOverlay === 'work'} onClose={closeOverlay} title="Selected Works">
           <Work isOverlay={true} />
        </Overlay>

        <Overlay isOpen={activeOverlay === 'insights'} onClose={closeOverlay} title="AI Insights">
           <div className="pt-8">
             <Insights />
           </div>
        </Overlay>

        <ContactOverlay isOpen={activeOverlay === 'contact'} onClose={closeOverlay} />

        <main>
          {/* Main Page Flow (Teaser View) */}
          <Hero startAnimation={introFinished} />
          <IsoWorld />
          <Business />
          <Clients />
          {/* Work Section on Main Page (The new list design) */}
          <Work />
          <Insights />
        </main>

        <Footer />
      </div>
    </div>
  );
};

