];

// Graph Configuration
const CANVAS_SIZE = 2500; // Draggable area size
const CONNECTION_DISTANCE = 400; // Reduced for tighter clusters

const Clients: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [hoveredNode, setHoveredNode] = useState<number | null>(null);

  // Generate random positions for nodes in a "Constellation" distribution
  const nodes = useMemo(() => {
    return CLIENT_LIST.map((client, index) => {
      // Use a spiral distribution but tighter and shifted
      const angle = index * 2.4; 
      // Reduced radius spread to gather them more in the center
      const radius = 50 + (index * 22) + (Math.random() * 40); 

      // Shift center slightly to Bottom-Right to avoid Top-Left Title overlap
      // CANVAS_SIZE/2 is the center of the draggable area (which aligns with screen center initially)
      const centerX = CANVAS_SIZE / 2 + 150; 
      const centerY = CANVAS_SIZE / 2 + 80;

      const x = centerX + Math.cos(angle) * radius * 1.2; 
      const y = centerY + Math.sin(angle) * radius * 0.9;

      return { ...client, x, y, id: index };
    });
  }, []);

  // Calculate lines (edges) between close nodes
  const edges = useMemo(() => {
    const lines: { from: number; to: number; distance: number }[] = [];
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < CONNECTION_DISTANCE) {
          lines.push({ from: i, to: j, distance });
        }
      }
    }
    return lines;
  }, [nodes]);

  return (
    <section className="relative w-full h-[120vh] bg-black overflow-hidden cursor-grab active:cursor-grabbing">

      {/* --- SCROLL SAFETY ZONE (RIGHT) --- */}
      {/* This area is not draggable, allowing users to scroll the page easily */}
      <div className="absolute top-0 right-0 w-16 md:w-24 h-full z-[60] bg-gradient-to-l from-black/80 to-transparent pointer-events-auto cursor-default flex flex-col items-center justify-center group">
         <div className="h-full w-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-500">
             <div className="h-32 w-[1px] bg-white/20 relative overflow-hidden rounded-full">
                <motion.div 
                   className="absolute top-0 w-full bg-[#FFB800]" 
                   style={{ height: '30%' }}
                   animate={{ top: ['0%', '100%'] }}
                   transition={{ duration: 2, repeat: Infinity, ease: 'linear' }}
                />
             </div>
         </div>
      </div>

      {/* Top Gradient for Seamless Connection */}
      <div className="absolute top-0 left-0 w-full h-40 bg-gradient-to-b from-black to-transparent z-10 pointer-events-none" />

      {/* Background Grid for Scale Reference */}
      <div 
        className="absolute inset-0 z-0 opacity-10 pointer-events-none" 
        style={{ 
          backgroundImage: 'radial-gradient(#333 1px, transparent 1px)', 
          backgroundSize: '40px 40px' 
        }} 
      />

      {/* Title Overlay (Fixed & Aligned) */}
      <div className="absolute top-0 left-0 w-full h-full pointer-events-none z-20 mix-blend-difference">
        <div className="container mx-auto px-6 pt-24 md:pt-32">
          <h2 className="text-6xl md:text-8xl font-extrabold tracking-tighter text-white leading-none mb-4">
            OUR <br/> <span className="text-gray-500">PARTNERS</span>
          </h2>
          <div className="flex items-center gap-3">
             <span className="w-2 h-2 bg-[#FFB800] rounded-full animate-pulse"/>
             <p className="text-sm md:text-base text-gray-400 font-bold tracking-widest uppercase">
              DRAG TO EXPLORE THE CONSTELLATION
             </p>
          </div>
        </div>
      </div>

      {/* Draggable Universe */}
      <motion.div
        ref={containerRef}
        className="relative w-full h-full flex items-center justify-center"
        drag
        dragConstraints={{ left: -1200, right: 1200, top: -1200, bottom: 1200 }}
        dragElastic={0.05}
        dragTransition={{ bounceStiffness: 100, bounceDamping: 10 }}
        whileTap={{ cursor: "grabbing" }}
      >
        <div 
          style={{ 
            width: CANVAS_SIZE, 
            height: CANVAS_SIZE, 
            position: 'absolute',
            left: `calc(50% - ${CANVAS_SIZE/2}px)`,
            top: `calc(50% - ${CANVAS_SIZE/2}px)`
          }}
        >
          {/* SVG Layer for Lines */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
            {edges.map((edge, i) => {
              const start = nodes[edge.from];
              const end = nodes[edge.to];
              const isConnectedToHover = hoveredNode === edge.from || hoveredNode === edge.to;

              return (
                <motion.line
                  key={`line-${i}`}
                  x1={start.x}
                  y1={start.y}
                  x2={end.x}
                  y2={end.y}
                  stroke={isConnectedToHover ? "#FFB800" : "#222"}
                  strokeWidth={isConnectedToHover ? 1.5 : 0.5}
                  initial={{ opacity: 0 }}
                  whileInView={{ opacity: isConnectedToHover ? 0.8 : 0.2 }}
                  viewport={{ once: true }}
                  transition={{ duration: 1 }}
                />
              );
            })}
          </svg>

          {/* Node Layer */}
          {nodes.map((node) => (
            <motion.div
              key={node.id}
              className="absolute group flex flex-col items-center justify-center text-center"
              style={{ 
                left: node.x, 
                top: node.y,
                transform: 'translate(-50%, -50%)',
                zIndex: hoveredNode === node.id ? 50 : 10
              }}
              onMouseEnter={() => setHoveredNode(node.id)}
              onMouseLeave={() => setHoveredNode(null)}
              initial={{ opacity: 0, scale: 0 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: Math.random() * 0.3 }}

              // Floating Animation
              animate={{
                y: [0, -8, 0],
              }}
              // @ts-ignore
              transition={{
                duration: 3 + Math.random() * 2,
                repeat: Infinity,
                ease: "easeInOut",
                delay: Math.random() * 2
              }}
            >
              {/* Interactive Node Wrapper */}
              <motion.div
                whileHover={{ scale: 1.2 }}
                transition={{ type: "spring", stiffness: 300, damping: 20 }}
                className="flex flex-col items-center justify-center"
              >
                {/* Dot */}
                <div 
                  className={`w-2 h-2 rounded-full mb-4 transition-all duration-300 
                    ${hoveredNode === node.id ? 'bg-[#FFB800] scale-[2] shadow-[0_0_20px_rgba(255,184,0,0.8)]' : 'bg-gray-600'}`} 
                />

                {/* Text Label */}
                <div className={`transition-all duration-300 ${hoveredNode === node.id ? 'scale-110' : 'scale-100 opacity-60'}`}>
                  <h3 className={`text-xl md:text-3xl font-extrabold tracking-tight whitespace-nowrap leading-none 
                    ${hoveredNode === node.id ? 'text-white' : 'text-gray-400'}`}>
