const CONNECTION_DISTANCE = 220; // Adjusted for density

const Clients: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [hoveredNode, setHoveredNode] = useState<number | null>(null);

  // Generate positions using Golden Spiral (Phyllotaxis)
  // Tighter packing to ensure they are seen together
  const nodes = useMemo(() => {
    const centerX = CANVAS_SIZE / 2;
    const centerY = CANVAS_SIZE / 2;

    // Significantly reduced spacing for a dense cluster
    // This makes the "organism" look solid and interconnected
    const SPACING = 140; 
    const GOLDEN_ANGLE = Math.PI * (3 - Math.sqrt(5)); 

    return CLIENT_LIST.map((client, index) => {
      // Sqrt(index) ensures uniform density
      const r = SPACING * Math.sqrt(index);
      const theta = index * GOLDEN_ANGLE;

      let x = centerX + r * Math.cos(theta);
      let y = centerY + r * Math.sin(theta);

      // Minimal jitter to keep it clean but organic
      const jitterX = (Math.random() - 0.5) * 20;
      const jitterY = (Math.random() - 0.5) * 20;

      x += jitterX;
      y += jitterY;

      return { ...client, x, y, id: index };
    });
  }, []);

  // Calculate lines (edges) between close nodes
  const edges = useMemo(() => {
    const lines: { from: number; to: number; distance: number }[] = [];
    for (let i = 0; i < nodes.length; i++) {
      for (let j = i + 1; j < nodes.length; j++) {
        const dx = nodes[i].x - nodes[j].x;
        const dy = nodes[i].y - nodes[j].y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < CONNECTION_DISTANCE) {
          lines.push({ from: i, to: j, distance });
        }
      }
    }
    return lines;
  }, [nodes]);

