            position: 'absolute',
            left: `calc(50% - ${CANVAS_SIZE/2}px)`,
            top: `calc(50% - ${CANVAS_SIZE/2}px)`
          }}
        >
          {/* SVG Layer for Lines */}
          <motion.svg 
            initial={{ opacity: 0 }}
            whileInView={{ opacity: 1 }}
            transition={{ duration: 1.5, delay: 0.5 }}
            className="absolute inset-0 w-full h-full pointer-events-none z-0"
          >
            {edges.map((edge, i) => {
              const start = nodes[edge.from];
              const end = nodes[edge.to];
              const isConnectedToHover = hoveredNode === edge.from || hoveredNode === edge.to;

              return (
                <motion.line
                  key={`line-${i}`}
                  x1={start.x}
                  y1={start.y}
                  x2={end.x}
                  y2={end.y}
