              OUR <br/> <span className="text-gray-500">PARTNERS</span>
            </h2>
            <div className="flex items-center gap-4">
               <div className="w-12 h-[2px] bg-[#FFB800]"></div>
               <p className="text-sm md:text-base text-gray-300 font-bold tracking-widest uppercase">
                Drag to Explore the Universe
               </p>
            </div>
          </motion.div>
        </div>
      </div>

      {/* Draggable Area */}
      <motion.div
        ref={containerRef}
        className="relative w-full h-full flex items-center justify-center"
        drag
        dragConstraints={{ left: -800, right: 800, top: -800, bottom: 800 }}
        dragElastic={0.1}
        dragTransition={{ power: 0.15, timeConstant: 250 }}
        whileTap={{ cursor: "grabbing" }}
      >
        {/* The Universe Container */}
        <motion.div
          variants={universeVariants}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true }}
          style={{ 
            width: CANVAS_SIZE, 
            height: CANVAS_SIZE, 
            position: 'absolute',
            left: `calc(50% - ${CANVAS_SIZE/2}px)`,
            top: `calc(50% - ${CANVAS_SIZE/2}px)`
          }}
        >
          {/* SVG Lines Layer */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0">
            {edges.map((edge, i) => {
              const start = nodes[edge.from];
              const end = nodes[edge.to];

              const isConnected = hoveredNode === edge.from || hoveredNode === edge.to;
              const isDimmed = hoveredNode !== null && !isConnected;

              return (
                <motion.line
                  key={`line-${i}`}
                  x1={start.x}
                  y1={start.y}
                  x2={end.x}
                  y2={end.y}
                  stroke={isConnected ? "#FFB800" : "#ffffff"}
                  strokeWidth={isConnected ? 1.5 : 0.5}
                  initial={false}
                  animate={{
                    opacity: isConnected ? 0.8 : (isDimmed ? 0.05 : 0.15),
                    stroke: isConnected ? "#FFB800" : "#555555"
                  }}
                  transition={{ duration: 0.4 }}
                />
              );
            })}
          </svg>

          {/* Nodes Layer */}
          {nodes.map((node) => {
            const isHovered = hoveredNode === node.id;
            const isNeighbor = hoveredNode !== null && edges.some(
              e => (e.from === hoveredNode && e.to === node.id) || (e.to === hoveredNode && e.from === node.id)
            );
            const isDimmed = hoveredNode !== null && !isHovered && !isNeighbor;

            return (
              <motion.div
                key={node.id}
                className="absolute flex flex-col items-center justify-center"
                style={{ 
                  left: node.x, 
                  top: node.y,
                  transform: 'translate(-50%, -50%)',
                  zIndex: isHovered ? 50 : 10
                }}
                onMouseEnter={() => setHoveredNode(node.id)}
                onMouseLeave={() => setHoveredNode(null)}
              >
                <motion.div
                  animate={{ 
                    y: [0, -4, 0],
                    x: [0, 2, 0]
                  }}
                  transition={{ 
                    duration: 4 + Math.random() * 3,
                    repeat: Infinity, 
                    ease: "easeInOut",
                    delay: Math.random() * -5
                  }}
                >
