                    animate={{
                      scale: isHovered ? 1.2 : (isDimmed ? 0.8 : 1),
                      opacity: isDimmed ? 0.2 : 1
                    }}
                    transition={{ duration: 0.4 }}
                    className="flex flex-col items-center justify-center cursor-pointer p-2"
                  >
