                    <div className="text-center relative">
                      <motion.h3 
                        className="text-xs md:text-sm font-bold whitespace-nowrap leading-none tracking-tight"
                        animate={{
                          color: isHovered ? "#ffffff" : "#888888",
                          scale: isHovered ? 1.1 : 1,
                          opacity: isHovered ? 1 : (isDimmed ? 0.3 : 0.7)
                        }}
                      >
                        {node.name}
                      </motion.h3>
                    </div>
                  </motion.div>
                </motion.div>
              </motion.div>
            );
          })}
        </motion.div>
      </motion.div>

      {/* Vignette for depth */}
      <div className="absolute inset-0 pointer-events-none bg-[radial-gradient(circle_at_center,transparent_0%,black_100%)] opacity-80" />
    </section>
  );
