        }} 
      />

      {/* Header */}
      <div className="absolute top-0 left-0 w-full z-20 pointer-events-none p-6 md:p-12">
        <div className="container mx-auto mt-24 md:mt-16">
          <motion.div
             initial={{ opacity: 0, y: 20 }}
             whileInView={{ opacity: 1, y: 0 }}
             viewport={{ once: true }}
