    setResult(data);
    setLoading(false);
  };

  return (
    <section id="insights" className="py-24 bg-[#050505] border-t border-white/5 relative overflow-hidden">
      {/* Background Decor */}
      <div className="absolute top-0 right-0 w-1/2 h-1/2 bg-[#FFB800]/10 rounded-full blur-[120px] pointer-events-none"></div>

