            <motion.form variants={itemVariants} onSubmit={handleGenerate} className="relative max-w-md">
              <input 
                type="text" 
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder="Enter industry (e.g., EV Cars, K-Beauty)"
