import React, { useEffect, useState } from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import IsoWorld from './components/IsoWorld';
import Business from './components/Business';
import Clients from './components/Clients';
import Work from './components/Work';
import Insights from './components/Insights';
import Footer from './components/Footer';
import AboutOverlay from './components/AboutOverlay';
import ContactOverlay from './components/ContactOverlay';
import Overlay from './components/Overlay';
import Intro from './components/Intro';
import { motion, useScroll, useSpring, AnimatePresence } from 'framer-motion';

const App: React.FC = () => {
  const { scrollYProgress } = useScroll();
  const scaleX = useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001
  });

  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [introFinished, setIntroFinished] = useState(false);
  const [showHeader, setShowHeader] = useState(true);

  // Overlay States
  const [activeOverlay, setActiveOverlay] = useState<string | null>(null);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    window.addEventListener("mousemove", handleMouseMove);
    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
    };
  }, []);

  const handleNavClick = (id: string) => {
    setActiveOverlay(id);
  };

  const closeOverlay = () => {
    setActiveOverlay(null);
  };

  return (
    <div className="bg-black min-h-screen text-white selection:bg-[#FFB800] selection:text-black cursor-none">

      {/* Intro Animation Layer */}
      <AnimatePresence mode="sync">
        {!introFinished && (
          <Intro onComplete={() => setIntroFinished(true)} />
        )}
      </AnimatePresence>

      {/* Main Content */}
      <div className="relative z-0">
        <Header 
          onNavClick={handleNavClick}
          show={showHeader} 
          introFinished={introFinished}
        />

        {/* Progress Bar */}
        {introFinished && (
          <motion.div
            className="fixed top-0 left-0 right-0 h-1 bg-[#FFB800] origin-left z-[60]"
            style={{ scaleX }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5 }}
          />
        )}

        {/* Custom Cursor */}
        <div 
          className="fixed top-0 left-0 w-8 h-8 bg-white rounded-full pointer-events-none mix-blend-difference z-[100] transform -translate-x-1/2 -translate-y-1/2 hidden md:block"
          style={{ 
            left: mousePosition.x, 
            top: mousePosition.y,
            transition: 'width 0.2s, height 0.2s',
          }}
        />

        {/* --- OVERLAYS --- */}
        <AboutOverlay isOpen={activeOverlay === 'about'} onClose={closeOverlay} />

        <Overlay isOpen={activeOverlay === 'business'} onClose={closeOverlay} title="Business Domain">
           <Business />
        </Overlay>

        <Overlay isOpen={activeOverlay === 'work'} onClose={closeOverlay} title="Selected Works">
           <Work isOverlay={true} />
        </Overlay>

        <Overlay isOpen={activeOverlay === 'insights'} onClose={closeOverlay} title="AI Insights">
           <Insights />
        </Overlay>

        <ContactOverlay isOpen={activeOverlay === 'contact'} onClose={closeOverlay} />

        <main>
          {/* Main Page Flow (Teaser View) */}
          <Hero startAnimation={introFinished} />
          <IsoWorld />
          <Business />
          <Clients />
          {/* Work and Insights sections removed from main flow as requested */}
        </main>

        <Footer />
      </div>
    </div>
  );
};

export default App;

